-- Extensions needed by this schema
CREATE EXTENSION IF NOT EXISTS pgcrypto; -- for gen_random_uuid()
CREATE EXTENSION IF NOT EXISTS citext;   -- case-insensitive email
CREATE EXTENSION IF NOT EXISTS pg_trgm;  -- trigram search for fast fuzzy matching
CREATE EXTENSION IF NOT EXISTS unaccent; -- accent-insensitive text search normalization

-- Applied migration ledger. Fresh databases get the table here; the bootstrap
-- upgrade step records each manifest migration after it has succeeded.
CREATE TABLE IF NOT EXISTS public.controller_schema_migration (
  migration_id text PRIMARY KEY,
  checksum text NOT NULL,
  description text NOT NULL,
  applied_at timestamptz NOT NULL DEFAULT now()
);

-- Optional pgvector extension for RAG/vector search storage. Dedicated
-- production Postgres servers may not have pgvector installed or may require
-- DBA-owned extension creation, so keep this best-effort and let schema init
-- continue without vector support.
DO $$
BEGIN
  IF EXISTS (
    SELECT 1
    FROM pg_available_extensions
    WHERE name = 'vector'
  ) THEN
    BEGIN
      CREATE EXTENSION IF NOT EXISTS vector;
    EXCEPTION WHEN OTHERS THEN
      RAISE NOTICE 'Skipping vector extension setup: %', SQLERRM;
    END;
  ELSE
    RAISE NOTICE 'Skipping vector extension setup: pgvector is not available in this database image.';
  END IF;
END
$$;

-- Optional Slovenian full-text search configuration for assistant/UNS search.
-- The official Postgres image does not ship Slovenian Hunspell files by
-- default.  When the image provides `slovenian.dict` and `slovenian.affix` in
-- PostgreSQL's tsearch_data directory, this creates `public.uns_slovenian`.
-- Otherwise init continues and the controller falls back to `simple` search.
DO $$
DECLARE
  has_slovenian_dictionary boolean := false;
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM pg_catalog.pg_ts_dict d
    JOIN pg_catalog.pg_namespace n ON n.oid = d.dictnamespace
    WHERE n.nspname = 'public'
      AND d.dictname = 'uns_slovenian_ispell'
  ) THEN
    BEGIN
      CREATE TEXT SEARCH DICTIONARY public.uns_slovenian_ispell (
        TEMPLATE = ispell,
        DictFile = slovenian,
        AffFile = slovenian
      );
      has_slovenian_dictionary := true;
    EXCEPTION WHEN OTHERS THEN
      RAISE NOTICE 'Skipping public.uns_slovenian text search config: %', SQLERRM;
    END;
  ELSE
    has_slovenian_dictionary := true;
  END IF;

  IF has_slovenian_dictionary THEN
    IF NOT EXISTS (
      SELECT 1
      FROM pg_catalog.pg_ts_config c
      JOIN pg_catalog.pg_namespace n ON n.oid = c.cfgnamespace
      WHERE n.nspname = 'public'
        AND c.cfgname = 'uns_slovenian'
    ) THEN
      CREATE TEXT SEARCH CONFIGURATION public.uns_slovenian (COPY = pg_catalog.simple);
    END IF;

    ALTER TEXT SEARCH CONFIGURATION public.uns_slovenian
      ALTER MAPPING FOR asciiword, asciihword, hword_asciipart, word, hword, hword_part
      WITH public.unaccent, public.uns_slovenian_ispell, pg_catalog.simple;
  END IF;
END
$$;

-- === AUTH TABLE ==============================================================
CREATE TABLE IF NOT EXISTS public.auth_refresh_tokens (
  tid uuid PRIMARY KEY,                 -- token id from JWT claim
  "userId" text NOT NULL,                 -- your user identifier
  "issuedAt" timestamptz NOT NULL DEFAULT now(),
  "expiresAt" timestamptz NOT NULL,       -- from JWT exp
  "revoked" boolean NOT NULL DEFAULT false,
  "rotatedFrom" uuid NULL,                -- prior tid when rotating
  "userAgent" text NULL,
  "ip" inet NULL,
  claims jsonb NULL
);

CREATE INDEX IF NOT EXISTS idx_auth_refresh_tokens_userId
  ON public.auth_refresh_tokens("userId");

CREATE INDEX IF NOT EXISTS idx_auth_refresh_tokens_expiresAt
  ON public.auth_refresh_tokens("expiresAt");

-- Handy for “active tokens for user” queries
CREATE INDEX IF NOT EXISTS idx_auth_refresh_tokens_user_active
  ON public.auth_refresh_tokens("userId", "expiresAt")
  WHERE revoked = false;

-- === UNS OBJECT TABLE ========================================================
CREATE TABLE IF NOT EXISTS public.uns_object
(
  id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "unsNode" varchar(60) NOT NULL,
  "parent" integer NULL,
  "description" varchar(100),
  "type" varchar(60),
  "processName" varchar(60),
  "processVersion" varchar(60),
  "attributeTimestamp" timestamptz,
  "attributeNeedsPersistance" boolean,
  "attributeTags" varchar[],
  "fullTopic" varchar(200) UNIQUE,
  "objectType" varchar(60),
  "objectId" varchar(60),
  "asset" varchar(60),
  "apiDescription" varchar(100),
  "apiMethod" varchar(10),
  "apiEndpoint" text,
  "attributeType" varchar(60),
  "dataGroup" varchar(60),
  "virtualGroup" varchar(60),
  "apiSwaggerEndpoint" text,
  "apiHost" text,
  "controllerName" varchar(100),
  "controllerHost" varchar(100),
  "controllerPort" varchar(20),
  "controllerPublicBase" text,
  "displayIcon" varchar(60),
  "displayColor" varchar(30),
  "archivedAt" timestamptz,
  "supersededByFullTopic" varchar(200)
);

ALTER TABLE public.uns_object
  ADD COLUMN IF NOT EXISTS "displayIcon" varchar(60);

ALTER TABLE public.uns_object
  ADD COLUMN IF NOT EXISTS "displayColor" varchar(30);

ALTER TABLE public.uns_object
  ADD COLUMN IF NOT EXISTS "archivedAt" timestamptz;

ALTER TABLE public.uns_object
  ADD COLUMN IF NOT EXISTS "supersededByFullTopic" varchar(200);

ALTER TABLE public.uns_object
  ADD COLUMN IF NOT EXISTS "descriptionConflict" varchar(200);

ALTER TABLE public.uns_object
  ADD COLUMN IF NOT EXISTS "virtualGroup" varchar(60);

ALTER TABLE public.uns_object
  ADD COLUMN IF NOT EXISTS "validityMode" varchar(20);

ALTER TABLE public.uns_object
  ADD COLUMN IF NOT EXISTS "expectedIntervalMs" integer;

ALTER TABLE public.uns_object
  ADD COLUMN IF NOT EXISTS "lifecycleEndValue" varchar(60);

ALTER TABLE public.uns_object
  ALTER COLUMN "apiEndpoint" TYPE text;

ALTER TABLE public.uns_object
  ALTER COLUMN "apiSwaggerEndpoint" TYPE text;

ALTER TABLE public.uns_object
  ALTER COLUMN "apiHost" TYPE text;

ALTER TABLE public.uns_object
  ALTER COLUMN "controllerPublicBase" TYPE text;

CREATE INDEX IF NOT EXISTS idx_uns_object_type_id
  ON public.uns_object("objectType", "objectId");

CREATE INDEX IF NOT EXISTS idx_uns_object_full_topic_trgm
  ON public.uns_object USING gin (lower("fullTopic") gin_trgm_ops);

CREATE INDEX IF NOT EXISTS idx_uns_object_uns_node_trgm
  ON public.uns_object USING gin (lower("unsNode") gin_trgm_ops);

CREATE INDEX IF NOT EXISTS idx_uns_object_description_trgm
  ON public.uns_object USING gin (lower("description") gin_trgm_ops);

CREATE INDEX IF NOT EXISTS idx_uns_object_search_tsv
  ON public.uns_object
  USING gin (
    to_tsvector(
      'simple',
      COALESCE("unsNode", '') || ' ' ||
      replace(COALESCE("fullTopic", ''), '/', ' ') || ' ' ||
      COALESCE("description", '') || ' ' ||
      COALESCE("asset", '') || ' ' ||
      COALESCE("objectType", '') || ' ' ||
      COALESCE("objectId", '') || ' ' ||
      COALESCE("attributeType", '')
    )
  );

DO $$
BEGIN
  IF EXISTS (
    SELECT 1
    FROM pg_catalog.pg_ts_config c
    JOIN pg_catalog.pg_namespace n ON n.oid = c.cfgnamespace
    WHERE n.nspname = 'public'
      AND c.cfgname = 'uns_slovenian'
  ) THEN
    EXECUTE $ddl$
      CREATE INDEX IF NOT EXISTS idx_uns_object_search_tsv_uns_slovenian
      ON public.uns_object
      USING gin (
        to_tsvector(
          'public.uns_slovenian'::regconfig,
          COALESCE("unsNode", '') || ' ' ||
          replace(COALESCE("fullTopic", ''), '/', ' ') || ' ' ||
          COALESCE("description", '') || ' ' ||
          COALESCE("asset", '') || ' ' ||
          COALESCE("objectType", '') || ' ' ||
          COALESCE("objectId", '') || ' ' ||
          COALESCE("attributeType", '')
        )
      )
    $ddl$;
  END IF;
END
$$;

CREATE INDEX IF NOT EXISTS idx_uns_object_archived_at
  ON public.uns_object("archivedAt");

CREATE INDEX IF NOT EXISTS idx_uns_object_attribute_tags
  ON public.uns_object USING gin ("attributeTags");

CREATE INDEX IF NOT EXISTS idx_uns_object_attribute_process_name
  ON public.uns_object("processName")
  WHERE "type" = 'Attribute' AND NULLIF(BTRIM(COALESCE("processName", '')), '') IS NOT NULL;

CREATE INDEX IF NOT EXISTS idx_uns_object_objectid_parent_timestamp
  ON public.uns_object("parent", "attributeTimestamp" DESC NULLS LAST)
  WHERE "type" = 'ObjectId';

CREATE INDEX IF NOT EXISTS idx_uns_object_attribute_parent_timestamp
  ON public.uns_object("parent", "attributeTimestamp" DESC NULLS LAST)
  WHERE "type" = 'Attribute';

