-- === QUESTDB MAPPINGS ======================================================
CREATE TABLE IF NOT EXISTS public."questdb_mappings" (
  id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "topicPrefix" varchar(200) NOT NULL,
  "tableName" varchar(200) NOT NULL,
  "tablePrefix" varchar(200) NOT NULL,
  "dataGroup" varchar(200) NULL,
  "suffix" varchar(50) NULL,
  "questdbUrl" varchar(200) NULL,
  "processName" varchar(200) NULL,
  "packageName" varchar(200) NULL,
  "version" varchar(50) NULL,
  "updatedAt" timestamptz NULL,
  CONSTRAINT uq_questdb_topic_table UNIQUE ("topicPrefix", "tableName")
);

CREATE INDEX IF NOT EXISTS idx_questdb_mappings_topic_prefix
  ON public."questdb_mappings" ("topicPrefix");

-- Keep history discovery independent from the active mapping projection.
CREATE TABLE IF NOT EXISTS public.questdb_history_sources (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "sourceKey" jsonb NOT NULL UNIQUE,
  "topicPrefix" varchar(200) NOT NULL,
  "tableName" varchar(200) NOT NULL,
  "tablePrefix" varchar(200) NOT NULL,
  "dataGroup" varchar(200), "suffix" varchar(50), "questdbUrl" varchar(200),
  "processName" varchar(200), "packageName" varchar(200), "version" varchar(50),
  "updatedAt" timestamptz,
  "firstObservedAt" timestamptz NOT NULL DEFAULT clock_timestamp(),
  "lastObservedAt" timestamptz NOT NULL DEFAULT clock_timestamp(),
  "retiredAt" timestamptz,
  revision bigint NOT NULL DEFAULT 1
);
CREATE INDEX IF NOT EXISTS idx_questdb_history_sources_topic
  ON public.questdb_history_sources ("topicPrefix");

-- Retention decisions survive the forgotten source; never cascade them away.
CREATE TABLE IF NOT EXISTS public.questdb_history_retention_events (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "sourceId" bigint NOT NULL, "sourceRevision" bigint NOT NULL,
  "topicPrefix" varchar(200) NOT NULL, "tableName" varchar(200) NOT NULL,
  "forgottenBy" text NOT NULL, "forgottenAt" timestamptz NOT NULL DEFAULT clock_timestamp()
);

-- Version is provenance, not physical source identity. Optional blanks and
-- NULL are equivalent; location/shape/owner changes must not hide ambiguity.
CREATE OR REPLACE FUNCTION public.questdb_history_source_key(mapping jsonb)
RETURNS jsonb LANGUAGE sql IMMUTABLE AS $$
  SELECT jsonb_build_array(
    COALESCE(mapping->>'topicPrefix', ''), COALESCE(mapping->>'tableName', ''),
    COALESCE(mapping->>'tablePrefix', ''), COALESCE(mapping->>'dataGroup', ''),
    COALESCE(mapping->>'suffix', ''), COALESCE(mapping->>'questdbUrl', ''),
    COALESCE(mapping->>'processName', ''), COALESCE(mapping->>'packageName', '')
  )
$$;

CREATE OR REPLACE FUNCTION public.capture_questdb_history_source()
RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE source public.questdb_mappings%ROWTYPE;
BEGIN
  IF TG_OP IN ('UPDATE', 'DELETE') THEN
    -- OLD may predate installation of the trigger. Preserve it before retiring.
    INSERT INTO public.questdb_history_sources
      ("sourceKey", "topicPrefix", "tableName", "tablePrefix", "dataGroup", "suffix", "questdbUrl", "processName", "packageName", "version", "updatedAt", "retiredAt")
    VALUES (public.questdb_history_source_key(to_jsonb(OLD)), OLD."topicPrefix", OLD."tableName", OLD."tablePrefix", OLD."dataGroup", OLD."suffix", OLD."questdbUrl", OLD."processName", OLD."packageName", OLD."version", OLD."updatedAt", clock_timestamp())
    ON CONFLICT ("sourceKey") DO UPDATE SET
      "retiredAt" = clock_timestamp(), revision = questdb_history_sources.revision + 1;
  END IF;
  IF TG_OP IN ('INSERT', 'UPDATE') THEN
    source := NEW;
    INSERT INTO public.questdb_history_sources
      ("sourceKey", "topicPrefix", "tableName", "tablePrefix", "dataGroup", "suffix", "questdbUrl", "processName", "packageName", "version", "updatedAt")
    VALUES (public.questdb_history_source_key(to_jsonb(source)), source."topicPrefix", source."tableName", source."tablePrefix", source."dataGroup", source."suffix", source."questdbUrl", source."processName", source."packageName", source."version", source."updatedAt")
    ON CONFLICT ("sourceKey") DO UPDATE SET
      "version" = EXCLUDED."version", "updatedAt" = EXCLUDED."updatedAt",
      "lastObservedAt" = clock_timestamp(), "retiredAt" = NULL,
      revision = questdb_history_sources.revision + 1;
  END IF;
  RETURN NULL;
END
$$;

-- Lock active writes until the backfill and trigger are installed together.
DROP TRIGGER IF EXISTS questdb_history_source_capture ON public.questdb_mappings;
CREATE TRIGGER questdb_history_source_capture AFTER INSERT OR UPDATE OR DELETE
  ON public.questdb_mappings FOR EACH ROW EXECUTE FUNCTION public.capture_questdb_history_source();
CREATE OR REPLACE FUNCTION public.retire_questdb_history_sources_before_truncate()
RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  UPDATE public.questdb_history_sources h
  SET "retiredAt" = clock_timestamp(), revision = h.revision + 1
  FROM public.questdb_mappings q
  WHERE h."sourceKey" = public.questdb_history_source_key(to_jsonb(q));
  RETURN NULL;
END
$$;
DROP TRIGGER IF EXISTS questdb_history_source_truncate ON public.questdb_mappings;
CREATE TRIGGER questdb_history_source_truncate BEFORE TRUNCATE
  ON public.questdb_mappings FOR EACH STATEMENT EXECUTE FUNCTION public.retire_questdb_history_sources_before_truncate();
INSERT INTO public.questdb_history_sources
  ("sourceKey", "topicPrefix", "tableName", "tablePrefix", "dataGroup", "suffix", "questdbUrl", "processName", "packageName", "version", "updatedAt")
SELECT public.questdb_history_source_key(to_jsonb(q)), q."topicPrefix", q."tableName", q."tablePrefix", q."dataGroup", q."suffix", q."questdbUrl", q."processName", q."packageName", q."version", q."updatedAt"
FROM public.questdb_mappings q
ON CONFLICT ("sourceKey") DO NOTHING;

-- Historical cleanup for stale snapshot rows: keep only the newest mapping per
-- source/topic/version, but only when the source identity is known.
WITH ranked_questdb_mappings AS (
  SELECT
    id,
    ROW_NUMBER() OVER (
      PARTITION BY
        "topicPrefix",
        "processName",
        "packageName",
        COALESCE("version", ''),
        COALESCE("dataGroup", ''),
        COALESCE("suffix", '')
      ORDER BY COALESCE("updatedAt", to_timestamp(0)) DESC,
               LENGTH(COALESCE("tablePrefix", '')) DESC,
               LENGTH(COALESCE("tableName", '')) DESC,
               id DESC
    ) AS rn
  FROM public."questdb_mappings"
  WHERE "processName" IS NOT NULL
    AND "packageName" IS NOT NULL
)
DELETE FROM public."questdb_mappings" q
USING ranked_questdb_mappings ranked
WHERE q.id = ranked.id
  AND ranked.rn > 1;

