  "key" text NOT NULL,
  label text NULL,
  description text NULL,
  from_object_type_key text NULL REFERENCES public.object_type_schema("key") ON DELETE SET NULL,
  to_object_type_key text NULL REFERENCES public.object_type_schema("key") ON DELETE SET NULL,
  relationship_kind text NOT NULL,
  direction text NOT NULL DEFAULT 'directed',
  cardinality text NOT NULL DEFAULT 'many_to_many',
  status text NOT NULL DEFAULT 'draft',
  schema_json jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by text NULL,
  updated_by text NULL,
  change_source text NULL,
  change_note text NULL,
  reviewed_by text NULL,
  reviewed_at timestamptz NULL,
  CONSTRAINT uq_object_relationship_schema_key UNIQUE ("key"),
  CONSTRAINT chk_object_relationship_schema_direction CHECK (direction IN ('directed', 'undirected')),
  CONSTRAINT chk_object_relationship_schema_cardinality CHECK (cardinality IN ('one_to_one', 'one_to_many', 'many_to_one', 'many_to_many')),
  CONSTRAINT chk_object_relationship_schema_status CHECK (status IN ('draft', 'active', 'deprecated'))
);

