CREATE TABLE IF NOT EXISTS public.object_id_relationship (
  id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  relationship_key text NOT NULL REFERENCES public.object_relationship_schema("key") ON DELETE RESTRICT,
  source_object_type text NOT NULL,
  source_object_id text NOT NULL,
  target_object_type text NOT NULL,
  target_object_id text NOT NULL,
  scope_key text NULL,
  source_stable_entity_id uuid NULL,
  target_stable_entity_id uuid NULL,
  endpoint_resolution_status text NOT NULL DEFAULT 'legacy',
  endpoint_resolution_evidence_json jsonb NOT NULL DEFAULT '{}'::jsonb,
  endpoint_resolved_at timestamptz NULL,
  endpoint_reviewed_by text NULL,
  source_uns_object_id integer NULL REFERENCES public.uns_object(id) ON DELETE SET NULL,
  target_uns_object_id integer NULL REFERENCES public.uns_object(id) ON DELETE SET NULL,
  source_full_topic text NULL,
  target_full_topic text NULL,
  evidence_attribute_full_topic text NULL,
  evidence_uns_object_id integer NULL REFERENCES public.uns_object(id) ON DELETE SET NULL,
  valid_from timestamptz NULL,
  valid_to timestamptz NULL,
  observed_at timestamptz NULL,
  confidence numeric NULL,
  status text NOT NULL DEFAULT 'suggested',
  source text NOT NULL DEFAULT 'schema_attribute',
  evidence_json jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by text NULL,
  updated_by text NULL,
  CONSTRAINT chk_object_id_relationship_status CHECK (status IN ('suggested', 'accepted', 'rejected', 'deprecated')),
  CONSTRAINT chk_object_id_relationship_confidence CHECK (confidence IS NULL OR (confidence >= 0 AND confidence <= 1))
);

