  CONSTRAINT chk_platform_package_installation_package_digest
    CHECK (package_digest ~ '^sha256:[0-9a-f]{64}$'),
  CONSTRAINT chk_platform_package_installation_profile_digest
    CHECK (profile_digest ~ '^sha256:[0-9a-f]{64}$')
);

CREATE INDEX IF NOT EXISTS idx_platform_package_installation_profile
  ON public.platform_package_installation (scope_key, profile_id, status);

CREATE TABLE IF NOT EXISTS public.platform_package_definition_ownership (
  scope_key text NOT NULL,
  definition_kind text NOT NULL,
  definition_key text NOT NULL,
  package_id text NOT NULL,
  package_version text NOT NULL,
  resource_key text NOT NULL,
  resource_digest text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (scope_key, definition_kind, definition_key),
  FOREIGN KEY (package_id, package_version, resource_key)
    REFERENCES public.platform_package_resource(package_id, package_version, resource_key) ON DELETE RESTRICT,
  CONSTRAINT chk_platform_package_definition_kind
    CHECK (definition_kind IN (
      'asset', 'attribute', 'object_type', 'relationship', 'measurement_unit',
      'state', 'event_type', 'action', 'view', 'navigation', 'policy'
    )),
  CONSTRAINT chk_platform_package_definition_resource_digest
    CHECK (resource_digest ~ '^sha256:[0-9a-f]{64}$')
);

CREATE INDEX IF NOT EXISTS idx_platform_package_definition_owner
  ON public.platform_package_definition_ownership (package_id, package_version, resource_key);

ALTER TABLE public.platform_package_definition_ownership
  DROP CONSTRAINT IF EXISTS chk_platform_package_definition_kind;

ALTER TABLE public.platform_package_definition_ownership
  ADD CONSTRAINT chk_platform_package_definition_kind
  CHECK (definition_kind IN (
    'asset', 'attribute', 'object_type', 'relationship', 'measurement_unit',
    'state', 'event_type', 'action', 'view', 'navigation', 'policy'
  ));

CREATE TABLE IF NOT EXISTS public.platform_schema_definition_projection (
  package_id text NOT NULL,
  package_version text NOT NULL,
  definition_kind text NOT NULL,
  qualified_key text NOT NULL,
  source_key text NOT NULL,
  legacy_key text NOT NULL,
  resource_key text NOT NULL,
  resource_digest text NOT NULL,
  source_content_digest text NOT NULL,
  projection_content_digest text NOT NULL,
  status text NOT NULL DEFAULT 'active',
  source_definition_json jsonb NOT NULL,
  projected_definition_json jsonb NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (package_id, package_version, definition_kind, qualified_key),
  UNIQUE (package_id, package_version, definition_kind, legacy_key),
  FOREIGN KEY (package_id, package_version, resource_key)
    REFERENCES public.platform_package_resource(package_id, package_version, resource_key) ON DELETE RESTRICT,
  CONSTRAINT chk_platform_schema_definition_projection_kind
    CHECK (definition_kind IN ('entity_type', 'attribute', 'relationship')),
  CONSTRAINT chk_platform_schema_definition_projection_status
    CHECK (status IN ('draft', 'active', 'deprecated')),
  CONSTRAINT chk_platform_schema_definition_projection_resource_digest
    CHECK (resource_digest ~ '^sha256:[0-9a-f]{64}$'),
  CONSTRAINT chk_platform_schema_definition_projection_source_digest
    CHECK (source_content_digest ~ '^sha256:[0-9a-f]{64}$'),
  CONSTRAINT chk_platform_schema_definition_projection_content_digest
    CHECK (projection_content_digest ~ '^sha256:[0-9a-f]{64}$'),
  CONSTRAINT chk_platform_schema_definition_projection_qualified_key
    CHECK (qualified_key ~ '^[a-z0-9]+(-[a-z0-9]+)*(\.[a-z0-9]+(-[a-z0-9]+)*)+$'),
  CONSTRAINT chk_platform_schema_definition_projection_legacy_key
    CHECK (legacy_key ~ '^[a-z0-9]+(-[a-z0-9]+)*$')
);

CREATE INDEX IF NOT EXISTS idx_platform_schema_definition_projection_lookup
  ON public.platform_schema_definition_projection
    (definition_kind, qualified_key, package_id, package_version);

CREATE INDEX IF NOT EXISTS idx_platform_schema_definition_projection_legacy
  ON public.platform_schema_definition_projection
    (definition_kind, legacy_key, package_id, package_version);

CREATE TABLE IF NOT EXISTS public.platform_schema_definition_alias (
  package_id text NOT NULL,
  package_version text NOT NULL,
  definition_kind text NOT NULL,
  qualified_key text NOT NULL,
  alias text NOT NULL,
  alias_kind text NOT NULL DEFAULT 'legacy_key',
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (package_id, package_version, definition_kind, alias),
  FOREIGN KEY (package_id, package_version, definition_kind, qualified_key)
    REFERENCES public.platform_schema_definition_projection
      (package_id, package_version, definition_kind, qualified_key)
    ON DELETE CASCADE,
  CONSTRAINT chk_platform_schema_definition_alias_kind
    CHECK (alias_kind IN ('legacy_key'))
);

CREATE INDEX IF NOT EXISTS idx_platform_schema_definition_alias_target
  ON public.platform_schema_definition_alias (definition_kind, qualified_key);

CREATE TABLE IF NOT EXISTS public.platform_semantic_definition (
  package_id text NOT NULL,
  package_version text NOT NULL,
  definition_kind text NOT NULL,
  qualified_key text NOT NULL,
  local_key text NOT NULL,
  resource_key text NOT NULL,
  resource_digest text NOT NULL,
  content_digest text NOT NULL,
  status text NOT NULL DEFAULT 'active',
  definition_json jsonb NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (package_id, package_version, definition_kind, qualified_key),
  FOREIGN KEY (package_id, package_version, resource_key)
    REFERENCES public.platform_package_resource(package_id, package_version, resource_key) ON DELETE RESTRICT,
  CONSTRAINT chk_platform_semantic_definition_kind
    CHECK (definition_kind IN ('state', 'event_type', 'action', 'view', 'navigation', 'policy')),
  CONSTRAINT chk_platform_semantic_definition_status
    CHECK (status IN ('draft', 'active', 'deprecated')),
  CONSTRAINT chk_platform_semantic_definition_resource_digest
    CHECK (resource_digest ~ '^sha256:[0-9a-f]{64}$'),
  CONSTRAINT chk_platform_semantic_definition_content_digest
    CHECK (content_digest ~ '^sha256:[0-9a-f]{64}$'),
  CONSTRAINT chk_platform_semantic_definition_qualified_key
    CHECK (qualified_key ~ '^[a-z0-9]+(-[a-z0-9]+)*(\.[a-z0-9]+(-[a-z0-9]+)*)+$'),
  CONSTRAINT chk_platform_semantic_definition_local_key
    CHECK (local_key ~ '^[a-z0-9]+(-[a-z0-9]+)*$')
);

CREATE INDEX IF NOT EXISTS idx_platform_semantic_definition_lookup
  ON public.platform_semantic_definition (definition_kind, qualified_key, package_id, package_version);

CREATE TABLE IF NOT EXISTS public.platform_semantic_definition_alias (
  package_id text NOT NULL,
  package_version text NOT NULL,
  definition_kind text NOT NULL,
  qualified_key text NOT NULL,
  alias text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (package_id, package_version, definition_kind, alias),
  FOREIGN KEY (package_id, package_version, definition_kind, qualified_key)
    REFERENCES public.platform_semantic_definition(package_id, package_version, definition_kind, qualified_key)
    ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS idx_platform_semantic_definition_alias_target
  ON public.platform_semantic_definition_alias (definition_kind, qualified_key);

CREATE TABLE IF NOT EXISTS public.platform_semantic_definition_overlay (
  scope_key text NOT NULL,
  definition_kind text NOT NULL,
  qualified_key text NOT NULL,
  base_package_id text NOT NULL,
  base_package_version text NOT NULL,
  overlay_json jsonb NOT NULL,
  content_digest text NOT NULL,
  updated_by text NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (scope_key, definition_kind, qualified_key),
  FOREIGN KEY (base_package_id, base_package_version, definition_kind, qualified_key)
    REFERENCES public.platform_semantic_definition(package_id, package_version, definition_kind, qualified_key)
    ON DELETE RESTRICT,
  CONSTRAINT chk_platform_semantic_definition_overlay_digest
    CHECK (content_digest ~ '^sha256:[0-9a-f]{64}$')
);

CREATE INDEX IF NOT EXISTS idx_platform_semantic_definition_overlay_base
  ON public.platform_semantic_definition_overlay
    (base_package_id, base_package_version, definition_kind, qualified_key);

CREATE TABLE IF NOT EXISTS public.schema_definition_source (
  scope_key text NOT NULL REFERENCES public.platform_tenant(scope_key) ON DELETE RESTRICT,
  definition_kind text NOT NULL,
  definition_key text NOT NULL,
  field_path text NOT NULL DEFAULT '',
  source_kind text NOT NULL,
  source_id text NOT NULL,
  source_version text NOT NULL DEFAULT '',
  content_digest text NOT NULL DEFAULT '',
  authority_level text NOT NULL,
  trust_status text NOT NULL DEFAULT 'not-applicable',
  status text NOT NULL DEFAULT 'active',
  first_seen_at timestamptz NOT NULL DEFAULT now(),
  last_seen_at timestamptz NOT NULL DEFAULT now(),
  evidence_json jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (
    scope_key, definition_kind, definition_key, field_path,
    source_kind, source_id, source_version, content_digest
  ),
  CONSTRAINT chk_schema_definition_source_definition_kind
    CHECK (definition_kind IN (
      'asset', 'attribute', 'object_type', 'relationship', 'measurement_unit',
      'state', 'event_type', 'action', 'view', 'navigation', 'policy'
    )),
  CONSTRAINT chk_schema_definition_source_kind
    CHECK (source_kind IN ('system', 'package', 'custom', 'service', 'mqtt', 'legacy-bridge')),
  CONSTRAINT chk_schema_definition_source_authority
    CHECK (authority_level IN ('authoritative', 'overlay', 'proposal', 'observation', 'compatibility')),
  CONSTRAINT chk_schema_definition_source_trust
    CHECK (trust_status IN ('trusted', 'untrusted', 'revoked', 'not-applicable')),
  CONSTRAINT chk_schema_definition_source_status
    CHECK (status IN ('active', 'stale', 'ignored')),
  CONSTRAINT chk_schema_definition_source_digest
    CHECK (content_digest = '' OR content_digest ~ '^sha256:[0-9a-f]{64}$'),
  CONSTRAINT chk_schema_definition_source_seen_range
    CHECK (last_seen_at >= first_seen_at)
);

CREATE UNIQUE INDEX IF NOT EXISTS uq_schema_definition_source_active
  ON public.schema_definition_source
    (scope_key, definition_kind, definition_key, field_path, source_kind, source_id)
  WHERE status = 'active';

CREATE INDEX IF NOT EXISTS idx_schema_definition_source_lookup
  ON public.schema_definition_source
    (scope_key, definition_kind, definition_key, status, source_kind);

-- Current tenant-owned definitions. Immutable history is captured by
-- tenant_schema_customization_revision. Reviewed service adoption copies
-- declarative content here without writing package or legacy projections.
CREATE TABLE IF NOT EXISTS public.tenant_schema_definition (
  scope_key text NOT NULL REFERENCES public.platform_tenant(scope_key) ON DELETE RESTRICT,
  definition_kind text NOT NULL,
  qualified_key text NOT NULL,
  content_digest text NOT NULL,
  definition_json jsonb NOT NULL,
  origin_kind text NOT NULL,
  source_id text NOT NULL,
  source_version text NOT NULL,
  source_contract_digest text NOT NULL,
  schema_id text NOT NULL,
  updated_by text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (scope_key, definition_kind, qualified_key),
  CONSTRAINT chk_tenant_schema_definition_kind
    CHECK (definition_kind IN (
      'asset', 'attribute', 'object_type', 'relationship', 'measurement_unit',
      'state', 'event_type', 'action', 'view', 'navigation', 'policy'
    )),
  CONSTRAINT chk_tenant_schema_definition_origin
    CHECK (origin_kind IN ('custom', 'service')),
  CONSTRAINT chk_tenant_schema_definition_content_digest
    CHECK (content_digest ~ '^sha256:[0-9a-f]{64}$'),
  CONSTRAINT chk_tenant_schema_definition_contract_digest
    CHECK (
      (origin_kind = 'service' AND source_contract_digest ~ '^sha256:[0-9a-f]{64}$') OR
      (origin_kind = 'custom' AND source_contract_digest = '')
    )
);

CREATE INDEX IF NOT EXISTS idx_tenant_schema_definition_source
  ON public.tenant_schema_definition (scope_key, origin_kind, source_id, source_contract_digest);

-- One immutable snapshot for every actually changed tenant customization.
-- Package artifacts remain immutable; this ledger pins the active package
-- composition and the tenant-owned overlays used to resolve the effective
-- schema. Draft/custom-definition/service-adoption fields are additive so the
-- same revision contract can grow without changing legacy schema tables.
CREATE TABLE IF NOT EXISTS public.tenant_schema_customization_revision (
  scope_key text NOT NULL REFERENCES public.platform_tenant(scope_key) ON DELETE RESTRICT,
  revision bigint NOT NULL CHECK (revision > 0),
  revision_digest text NOT NULL,
  status text NOT NULL DEFAULT 'applied',
  base_profile_id text NULL,
  base_profile_digest text NULL,
  operation_id uuid NOT NULL,
  request_digest text NOT NULL,
  trigger_kind text NOT NULL,
  customization_json jsonb NOT NULL,
  changed_by text NOT NULL,
  applied_at timestamptz NOT NULL DEFAULT now(),
  superseded_at timestamptz NULL,
  PRIMARY KEY (scope_key, revision),
  UNIQUE (scope_key, operation_id),
  CONSTRAINT chk_tenant_schema_customization_revision_digest
    CHECK (revision_digest ~ '^sha256:[0-9a-f]{64}$'),
  CONSTRAINT chk_tenant_schema_customization_request_digest
    CHECK (request_digest ~ '^sha256:[0-9a-f]{64}$'),
  CONSTRAINT chk_tenant_schema_customization_profile_digest
    CHECK (base_profile_digest IS NULL OR base_profile_digest ~ '^sha256:[0-9a-f]{64}$'),
  CONSTRAINT chk_tenant_schema_customization_status
    CHECK (status IN ('applied', 'superseded')),
  CONSTRAINT chk_tenant_schema_customization_trigger
    CHECK (trigger_kind IN ('semantic-overlay', 'customization', 'service-adoption', 'reset', 'rollback', 'legacy-projection')),
  CONSTRAINT chk_tenant_schema_customization_state
    CHECK (
      (status = 'applied' AND superseded_at IS NULL) OR
      (status = 'superseded' AND superseded_at IS NOT NULL)
    )
);

CREATE UNIQUE INDEX IF NOT EXISTS uq_tenant_schema_customization_applied
  ON public.tenant_schema_customization_revision (scope_key)
  WHERE status = 'applied';

CREATE INDEX IF NOT EXISTS idx_tenant_schema_customization_history
  ON public.tenant_schema_customization_revision (scope_key, revision DESC);

-- One explicit owner and optional tenant revision binding for the remaining
-- global mutable schema compatibility projection. The initial record is
-- deliberately unbound: package activation, tenant customization, and MQTT
-- discovery cannot claim this global bridge implicitly.
CREATE TABLE IF NOT EXISTS public.legacy_schema_projection_state (
  projection_key text PRIMARY KEY,
  owner_id text NOT NULL,
  lifecycle_state text NOT NULL DEFAULT 'unbound',
  selected_scope_key text NULL,
  selected_revision bigint NULL,
  selected_revision_digest text NULL,
  projection_version bigint NOT NULL DEFAULT 1 CHECK (projection_version > 0),
  updated_by text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT chk_legacy_schema_projection_key
    CHECK (projection_key = 'global-compatibility'),
  CONSTRAINT chk_legacy_schema_projection_owner
    CHECK (owner_id = 'controller:global-schema-catalog'),
  CONSTRAINT chk_legacy_schema_projection_lifecycle
    CHECK (lifecycle_state IN ('unbound', 'bound', 'retired')),
  CONSTRAINT chk_legacy_schema_projection_revision_digest
    CHECK (
      selected_revision_digest IS NULL OR
      selected_revision_digest ~ '^sha256:[0-9a-f]{64}$'
    ),
  CONSTRAINT chk_legacy_schema_projection_binding
    CHECK (
      (
        lifecycle_state = 'bound' AND
        selected_scope_key IS NOT NULL AND
        selected_revision IS NOT NULL AND
        selected_revision_digest IS NOT NULL
      ) OR (
        lifecycle_state IN ('unbound', 'retired') AND
        selected_scope_key IS NULL AND
        selected_revision IS NULL AND
        selected_revision_digest IS NULL
      )
    ),
  CONSTRAINT fk_legacy_schema_projection_revision
    FOREIGN KEY (selected_scope_key, selected_revision)
    REFERENCES public.tenant_schema_customization_revision(scope_key, revision)
    ON DELETE RESTRICT
);

INSERT INTO public.legacy_schema_projection_state
  (projection_key, owner_id, lifecycle_state, updated_by)
VALUES
  ('global-compatibility', 'controller:global-schema-catalog', 'unbound', 'system:init')
ON CONFLICT (projection_key) DO NOTHING;

-- Immutable before/after evidence for every mutation of the remaining global
-- compatibility projection. Semantic snapshots make rollback independent of
-- current package activation or MQTT discovery state.
CREATE TABLE IF NOT EXISTS public.legacy_schema_projection_revision (
  revision bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  operation_id uuid NOT NULL UNIQUE,
  operation_kind text NOT NULL,
  scope_key text NOT NULL REFERENCES public.platform_tenant(scope_key) ON DELETE RESTRICT,
  target_scope_key text NULL,
  target_customization_revision bigint NULL,
  target_revision_digest text NULL,
  projection_version bigint NOT NULL CHECK (projection_version > 0),
  expected_plan_digest text NOT NULL,
  request_digest text NOT NULL,
  before_state_json jsonb NOT NULL,
  after_state_json jsonb NOT NULL,
  before_snapshot_json jsonb NOT NULL,
  after_snapshot_json jsonb NOT NULL,
  before_snapshot_digest text NOT NULL,
  after_snapshot_digest text NOT NULL,
  changed_by text NOT NULL,
  applied_at timestamptz NOT NULL DEFAULT now(),
  rolled_back_from_revision bigint NULL,
  CONSTRAINT chk_legacy_schema_projection_revision_operation
    CHECK (operation_kind IN ('replace', 'retire', 'rollback')),
  CONSTRAINT chk_legacy_schema_projection_revision_target
    CHECK (
      (
        target_scope_key IS NULL AND
        target_customization_revision IS NULL AND
        target_revision_digest IS NULL
      ) OR (
        target_scope_key IS NOT NULL AND
        target_customization_revision IS NOT NULL AND
        target_revision_digest IS NOT NULL
      )
    ),
  CONSTRAINT chk_legacy_schema_projection_revision_target_digest
    CHECK (target_revision_digest IS NULL OR target_revision_digest ~ '^sha256:[0-9a-f]{64}$'),
  CONSTRAINT chk_legacy_schema_projection_revision_plan_digest
    CHECK (expected_plan_digest ~ '^sha256:[0-9a-f]{64}$'),
  CONSTRAINT chk_legacy_schema_projection_revision_request_digest
    CHECK (request_digest ~ '^sha256:[0-9a-f]{64}$'),
  CONSTRAINT chk_legacy_schema_projection_revision_before_digest
    CHECK (before_snapshot_digest ~ '^sha256:[0-9a-f]{64}$'),
  CONSTRAINT chk_legacy_schema_projection_revision_after_digest
    CHECK (after_snapshot_digest ~ '^sha256:[0-9a-f]{64}$'),
  CONSTRAINT fk_legacy_schema_projection_revision_target
    FOREIGN KEY (target_scope_key, target_customization_revision)
    REFERENCES public.tenant_schema_customization_revision(scope_key, revision)
    ON DELETE RESTRICT,
  CONSTRAINT fk_legacy_schema_projection_revision_rollback
    FOREIGN KEY (rolled_back_from_revision)
    REFERENCES public.legacy_schema_projection_revision(revision)
    ON DELETE RESTRICT
);

CREATE INDEX IF NOT EXISTS idx_legacy_schema_projection_revision_applied
  ON public.legacy_schema_projection_revision (applied_at DESC, revision DESC);

CREATE INDEX IF NOT EXISTS idx_legacy_schema_projection_revision_scope
  ON public.legacy_schema_projection_revision (scope_key, revision DESC);

CREATE TABLE IF NOT EXISTS public.platform_package_audit (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  scope_key text NOT NULL,
  event_type text NOT NULL,
  profile_id text NULL,
  profile_digest text NULL,
  package_id text NULL,
  package_version text NULL,
  package_digest text NULL,
  operation_id uuid NULL,
  request_digest text NULL,
  changed_by text NULL,
  details_json jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT chk_platform_package_audit_request_digest
    CHECK (request_digest IS NULL OR request_digest ~ '^sha256:[0-9a-f]{64}$')
);

ALTER TABLE public.platform_package_audit
  ADD COLUMN IF NOT EXISTS operation_id uuid;
ALTER TABLE public.platform_package_audit
  ADD COLUMN IF NOT EXISTS request_digest text;

ALTER TABLE public.platform_package_audit
  DROP CONSTRAINT IF EXISTS chk_platform_package_audit_request_digest;
ALTER TABLE public.platform_package_audit
  ADD CONSTRAINT chk_platform_package_audit_request_digest
  CHECK (request_digest IS NULL OR request_digest ~ '^sha256:[0-9a-f]{64}$');

CREATE UNIQUE INDEX IF NOT EXISTS uq_platform_package_audit_scope_operation
  ON public.platform_package_audit (scope_key, operation_id)
  WHERE operation_id IS NOT NULL;

CREATE INDEX IF NOT EXISTS idx_platform_package_audit_scope_created_at
  ON public.platform_package_audit (scope_key, created_at DESC);

CREATE INDEX IF NOT EXISTS idx_platform_package_audit_package_created_at
  ON public.platform_package_audit (package_id, package_version, created_at DESC);

-- Tenant-scoped authoring drafts are mutable working copies. Validation rows
-- retain the exact reviewed revision and are intentionally append-only.
CREATE TABLE IF NOT EXISTS public.platform_package_candidate_draft (
  scope_key text NOT NULL REFERENCES public.platform_tenant(scope_key) ON DELETE RESTRICT,
  draft_id uuid NOT NULL DEFAULT gen_random_uuid(),
  package_id text NOT NULL,
  base_package_version text NOT NULL,
  base_package_digest text NOT NULL,
  candidate_package_version text NOT NULL,
  candidate_digest text NOT NULL,
  revision integer NOT NULL DEFAULT 1 CHECK (revision > 0),
  status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'discarded')),
  candidate_json jsonb NOT NULL,
  created_by text NOT NULL,
  updated_by text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  discarded_by text NULL,
  discarded_at timestamptz NULL,
  PRIMARY KEY (scope_key, draft_id),
  CONSTRAINT chk_platform_package_candidate_draft_base_digest
    CHECK (base_package_digest ~ '^sha256:[0-9a-f]{64}$'),
  CONSTRAINT chk_platform_package_candidate_draft_candidate_digest
    CHECK (candidate_digest ~ '^sha256:[0-9a-f]{64}$'),
  CONSTRAINT chk_platform_package_candidate_draft_discard_state
    CHECK (
      (status = 'draft' AND discarded_by IS NULL AND discarded_at IS NULL) OR
      (status = 'discarded' AND discarded_by IS NOT NULL AND discarded_at IS NOT NULL)
    )
);

CREATE UNIQUE INDEX IF NOT EXISTS uq_platform_package_candidate_draft_owner_active
  ON public.platform_package_candidate_draft
    (scope_key, package_id, base_package_version, created_by)
  WHERE status = 'draft';

CREATE INDEX IF NOT EXISTS idx_platform_package_candidate_draft_scope_updated
  ON public.platform_package_candidate_draft (scope_key, status, updated_at DESC);

CREATE TABLE IF NOT EXISTS public.platform_package_candidate_validation (
  scope_key text NOT NULL,
  validation_id uuid NOT NULL DEFAULT gen_random_uuid(),
  draft_id uuid NOT NULL,
  draft_revision integer NOT NULL CHECK (draft_revision > 0),
  candidate_digest text NOT NULL,
  candidate_json jsonb NOT NULL,
  valid boolean NOT NULL,
  result_json jsonb NOT NULL,
  validated_by text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (scope_key, validation_id),
  FOREIGN KEY (scope_key, draft_id)
    REFERENCES public.platform_package_candidate_draft(scope_key, draft_id) ON DELETE RESTRICT,
  CONSTRAINT chk_platform_package_candidate_validation_digest
    CHECK (candidate_digest ~ '^sha256:[0-9a-f]{64}$')
);

CREATE INDEX IF NOT EXISTS idx_platform_package_candidate_validation_history
  ON public.platform_package_candidate_validation
    (scope_key, draft_id, created_at DESC, validation_id DESC);

CREATE OR REPLACE FUNCTION public.reject_platform_package_candidate_validation_mutation()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  RAISE EXCEPTION 'platform package candidate validations are immutable'
    USING ERRCODE = '55000';
END;
$$;

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM pg_trigger
    WHERE tgname = 'trg_platform_package_candidate_validation_immutable'
      AND tgrelid = 'public.platform_package_candidate_validation'::regclass
  ) THEN
    CREATE TRIGGER trg_platform_package_candidate_validation_immutable
      BEFORE UPDATE OR DELETE ON public.platform_package_candidate_validation
      FOR EACH ROW EXECUTE FUNCTION public.reject_platform_package_candidate_validation_mutation();
  END IF;
END
$$;

-- Review submissions and their final decisions are separate append-only
-- evidence. A decision is bound to one exact successful validation and cannot
-- be made by the submitter.
CREATE TABLE IF NOT EXISTS public.platform_package_candidate_review (
  scope_key text NOT NULL,
  review_id uuid NOT NULL DEFAULT gen_random_uuid(),
  draft_id uuid NOT NULL,
  validation_id uuid NOT NULL,
  draft_revision integer NOT NULL CHECK (draft_revision > 0),
  candidate_digest text NOT NULL,
  package_id text NOT NULL,
  candidate_package_version text NOT NULL,
  submitted_by text NOT NULL,
  requires_four_eyes boolean NOT NULL DEFAULT false,
  submission_note text NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (scope_key, review_id),
  UNIQUE (scope_key, validation_id),
  FOREIGN KEY (scope_key, draft_id)
    REFERENCES public.platform_package_candidate_draft(scope_key, draft_id) ON DELETE RESTRICT,
  FOREIGN KEY (scope_key, validation_id)
    REFERENCES public.platform_package_candidate_validation(scope_key, validation_id) ON DELETE RESTRICT,
  CONSTRAINT chk_platform_package_candidate_review_digest
    CHECK (candidate_digest ~ '^sha256:[0-9a-f]{64}$'),
  CONSTRAINT chk_platform_package_candidate_review_submitter
    CHECK (length(btrim(submitted_by)) > 0),
  CONSTRAINT chk_platform_package_candidate_review_note
    CHECK (submission_note IS NULL OR length(submission_note) <= 2000)
);

ALTER TABLE public.platform_package_candidate_review
  ADD COLUMN IF NOT EXISTS requires_four_eyes boolean;

UPDATE public.platform_package_candidate_review
SET requires_four_eyes = true
WHERE requires_four_eyes IS NULL;

ALTER TABLE public.platform_package_candidate_review
  ALTER COLUMN requires_four_eyes SET DEFAULT false,
  ALTER COLUMN requires_four_eyes SET NOT NULL;

CREATE INDEX IF NOT EXISTS idx_platform_package_candidate_review_scope_created
  ON public.platform_package_candidate_review (scope_key, created_at DESC, review_id DESC);

CREATE TABLE IF NOT EXISTS public.platform_package_candidate_review_decision (
  scope_key text NOT NULL,
  decision_id uuid NOT NULL DEFAULT gen_random_uuid(),
  review_id uuid NOT NULL,
  validation_id uuid NOT NULL,
  candidate_digest text NOT NULL,
  decision text NOT NULL CHECK (decision IN ('approved', 'rejected')),
  decided_by text NOT NULL,
  decision_note text NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (scope_key, decision_id),
  UNIQUE (scope_key, review_id),
  FOREIGN KEY (scope_key, review_id)
    REFERENCES public.platform_package_candidate_review(scope_key, review_id) ON DELETE RESTRICT,
  FOREIGN KEY (scope_key, validation_id)
    REFERENCES public.platform_package_candidate_validation(scope_key, validation_id) ON DELETE RESTRICT,
  CONSTRAINT chk_platform_package_candidate_review_decision_digest
    CHECK (candidate_digest ~ '^sha256:[0-9a-f]{64}$'),
  CONSTRAINT chk_platform_package_candidate_review_decider
    CHECK (length(btrim(decided_by)) > 0),
  CONSTRAINT chk_platform_package_candidate_review_decision_note
    CHECK (decision_note IS NULL OR length(decision_note) <= 2000),
  CONSTRAINT chk_platform_package_candidate_review_rejection_note
    CHECK (decision <> 'rejected' OR length(btrim(decision_note)) > 0)
);

CREATE OR REPLACE FUNCTION public.validate_platform_package_candidate_review_decision()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  expected_validation_id uuid;
  expected_candidate_digest text;
  expected_submitter text;
  expected_requires_four_eyes boolean;
  expected_draft_revision integer;
  current_draft_revision integer;
  current_candidate_digest text;
  current_draft_status text;
BEGIN
  SELECT review.validation_id, review.candidate_digest, review.submitted_by, review.requires_four_eyes,
         review.draft_revision, draft.revision, draft.candidate_digest, draft.status
  INTO expected_validation_id, expected_candidate_digest, expected_submitter, expected_requires_four_eyes,
       expected_draft_revision, current_draft_revision, current_candidate_digest, current_draft_status
  FROM public.platform_package_candidate_review review
  JOIN public.platform_package_candidate_draft draft
    ON draft.scope_key = review.scope_key AND draft.draft_id = review.draft_id
  WHERE review.scope_key = NEW.scope_key
    AND review.review_id = NEW.review_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'platform package candidate review was not found'
      USING ERRCODE = '23503';
  END IF;
  IF NEW.validation_id <> expected_validation_id
    OR NEW.candidate_digest <> expected_candidate_digest THEN
    RAISE EXCEPTION 'platform package candidate review decision evidence does not match its review'
      USING ERRCODE = '23514';
  END IF;
  IF expected_requires_four_eyes
    AND lower(btrim(NEW.decided_by)) = lower(btrim(expected_submitter)) THEN
    RAISE EXCEPTION 'platform package candidate review submitter cannot decide their own review'
      USING ERRCODE = '23514';
  END IF;
  IF current_draft_status <> 'draft'
    OR current_draft_revision <> expected_draft_revision
    OR current_candidate_digest <> expected_candidate_digest THEN
    RAISE EXCEPTION 'platform package candidate review is superseded'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION public.reject_platform_package_candidate_review_mutation()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  RAISE EXCEPTION 'platform package candidate review evidence is immutable'
    USING ERRCODE = '55000';
END;
$$;

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_trigger
    WHERE tgname = 'trg_platform_package_candidate_review_decision_binding'
      AND tgrelid = 'public.platform_package_candidate_review_decision'::regclass
  ) THEN
    CREATE TRIGGER trg_platform_package_candidate_review_decision_binding
      BEFORE INSERT ON public.platform_package_candidate_review_decision
      FOR EACH ROW EXECUTE FUNCTION public.validate_platform_package_candidate_review_decision();
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM pg_trigger
    WHERE tgname = 'trg_platform_package_candidate_review_immutable'
      AND tgrelid = 'public.platform_package_candidate_review'::regclass
  ) THEN
    CREATE TRIGGER trg_platform_package_candidate_review_immutable
      BEFORE UPDATE OR DELETE ON public.platform_package_candidate_review
      FOR EACH ROW EXECUTE FUNCTION public.reject_platform_package_candidate_review_mutation();
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM pg_trigger
    WHERE tgname = 'trg_platform_package_candidate_review_decision_immutable'
      AND tgrelid = 'public.platform_package_candidate_review_decision'::regclass
  ) THEN
    CREATE TRIGGER trg_platform_package_candidate_review_decision_immutable
      BEFORE UPDATE OR DELETE ON public.platform_package_candidate_review_decision
      FOR EACH ROW EXECUTE FUNCTION public.reject_platform_package_candidate_review_mutation();
  END IF;
END
$$;

-- Tenant-scoped solution-profile authoring drafts. Manifest semantic version
-- identifies publishable content; revision is only the optimistic authoring
-- counter. Successful validations retain the exact manifest bytes and digest.
CREATE TABLE IF NOT EXISTS public.solution_profile_candidate_draft (
  scope_key text NOT NULL REFERENCES public.platform_tenant(scope_key) ON DELETE RESTRICT,
  draft_id uuid NOT NULL DEFAULT gen_random_uuid(),
  profile_id text NOT NULL,
  candidate_profile_version text NOT NULL,
  candidate_digest text NOT NULL,
  revision integer NOT NULL DEFAULT 1 CHECK (revision > 0),
  status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'discarded')),
  manifest_json jsonb NOT NULL,
  manifest_text text NOT NULL,
  created_by text NOT NULL,
  updated_by text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  discarded_by text NULL,
  discarded_at timestamptz NULL,
  PRIMARY KEY (scope_key, draft_id),
  CONSTRAINT chk_solution_profile_candidate_draft_digest
    CHECK (candidate_digest ~ '^sha256:[0-9a-f]{64}$'),
  CONSTRAINT chk_solution_profile_candidate_draft_discard_state
    CHECK (
      (status = 'draft' AND discarded_by IS NULL AND discarded_at IS NULL) OR
      (status = 'discarded' AND discarded_by IS NOT NULL AND discarded_at IS NOT NULL)
    )
);

CREATE UNIQUE INDEX IF NOT EXISTS uq_solution_profile_candidate_draft_owner_active
  ON public.solution_profile_candidate_draft (scope_key, profile_id, created_by)
  WHERE status = 'draft';

CREATE INDEX IF NOT EXISTS idx_solution_profile_candidate_draft_scope_updated
  ON public.solution_profile_candidate_draft (scope_key, status, updated_at DESC);

CREATE TABLE IF NOT EXISTS public.solution_profile_candidate_validation (
  scope_key text NOT NULL,
  validation_id uuid NOT NULL DEFAULT gen_random_uuid(),
  draft_id uuid NOT NULL,
  draft_revision integer NOT NULL CHECK (draft_revision > 0),
  candidate_digest text NOT NULL,
  manifest_json jsonb NOT NULL,
  manifest_text text NOT NULL,
  result_json jsonb NOT NULL,
  validated_by text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (scope_key, validation_id),
  FOREIGN KEY (scope_key, draft_id)
    REFERENCES public.solution_profile_candidate_draft(scope_key, draft_id) ON DELETE RESTRICT,
  CONSTRAINT chk_solution_profile_candidate_validation_digest
    CHECK (candidate_digest ~ '^sha256:[0-9a-f]{64}$')
);

CREATE INDEX IF NOT EXISTS idx_solution_profile_candidate_validation_history
  ON public.solution_profile_candidate_validation
    (scope_key, draft_id, created_at DESC, validation_id DESC);

CREATE OR REPLACE FUNCTION public.reject_solution_profile_candidate_validation_mutation()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  RAISE EXCEPTION 'solution profile candidate validations are immutable'
    USING ERRCODE = '55000';
END;
$$;

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_trigger
    WHERE tgname = 'trg_solution_profile_candidate_validation_immutable'
      AND tgrelid = 'public.solution_profile_candidate_validation'::regclass
  ) THEN
    CREATE TRIGGER trg_solution_profile_candidate_validation_immutable
      BEFORE UPDATE OR DELETE ON public.solution_profile_candidate_validation
      FOR EACH ROW EXECUTE FUNCTION public.reject_solution_profile_candidate_validation_mutation();
  END IF;
END
$$;

-- Immutable four-eyes review evidence for exact, successfully validated
-- solution-profile candidate revisions. Approval does not publish or install.
CREATE TABLE IF NOT EXISTS public.solution_profile_candidate_review (
  scope_key text NOT NULL,
  review_id uuid NOT NULL DEFAULT gen_random_uuid(),
  draft_id uuid NOT NULL,
  validation_id uuid NOT NULL,
  draft_revision integer NOT NULL CHECK (draft_revision > 0),
  candidate_digest text NOT NULL,
  profile_id text NOT NULL,
  candidate_profile_version text NOT NULL,
  submitted_by text NOT NULL,
  requires_four_eyes boolean NOT NULL DEFAULT false,
  submission_note text NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (scope_key, review_id),
  UNIQUE (scope_key, validation_id),
  FOREIGN KEY (scope_key, draft_id)
    REFERENCES public.solution_profile_candidate_draft(scope_key, draft_id) ON DELETE RESTRICT,
  FOREIGN KEY (scope_key, validation_id)
    REFERENCES public.solution_profile_candidate_validation(scope_key, validation_id) ON DELETE RESTRICT,
  CONSTRAINT chk_solution_profile_candidate_review_digest
    CHECK (candidate_digest ~ '^sha256:[0-9a-f]{64}$'),
  CONSTRAINT chk_solution_profile_candidate_review_submitter
    CHECK (length(btrim(submitted_by)) > 0),
  CONSTRAINT chk_solution_profile_candidate_review_note
    CHECK (submission_note IS NULL OR length(submission_note) <= 2000)
);

ALTER TABLE public.solution_profile_candidate_review
  ADD COLUMN IF NOT EXISTS requires_four_eyes boolean;

UPDATE public.solution_profile_candidate_review
SET requires_four_eyes = true
WHERE requires_four_eyes IS NULL;

ALTER TABLE public.solution_profile_candidate_review
  ALTER COLUMN requires_four_eyes SET DEFAULT false,
  ALTER COLUMN requires_four_eyes SET NOT NULL;

CREATE INDEX IF NOT EXISTS idx_solution_profile_candidate_review_scope_created
  ON public.solution_profile_candidate_review (scope_key, created_at DESC, review_id DESC);

CREATE TABLE IF NOT EXISTS public.solution_profile_candidate_review_decision (
  scope_key text NOT NULL,
  decision_id uuid NOT NULL DEFAULT gen_random_uuid(),
  review_id uuid NOT NULL,
  validation_id uuid NOT NULL,
  candidate_digest text NOT NULL,
  decision text NOT NULL CHECK (decision IN ('approved', 'rejected')),
  decided_by text NOT NULL,
  decision_note text NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (scope_key, decision_id),
  UNIQUE (scope_key, review_id),
  FOREIGN KEY (scope_key, review_id)
    REFERENCES public.solution_profile_candidate_review(scope_key, review_id) ON DELETE RESTRICT,
  FOREIGN KEY (scope_key, validation_id)
    REFERENCES public.solution_profile_candidate_validation(scope_key, validation_id) ON DELETE RESTRICT,
  CONSTRAINT chk_solution_profile_candidate_review_decision_digest
    CHECK (candidate_digest ~ '^sha256:[0-9a-f]{64}$'),
  CONSTRAINT chk_solution_profile_candidate_review_decider
    CHECK (length(btrim(decided_by)) > 0),
  CONSTRAINT chk_solution_profile_candidate_review_decision_note
    CHECK (decision_note IS NULL OR length(decision_note) <= 2000),
  CONSTRAINT chk_solution_profile_candidate_review_rejection_note
    CHECK (decision <> 'rejected' OR length(btrim(decision_note)) > 0)
);

CREATE OR REPLACE FUNCTION public.validate_solution_profile_candidate_review_decision()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  expected_validation_id uuid;
  expected_candidate_digest text;
  expected_submitter text;
  expected_requires_four_eyes boolean;
  expected_draft_revision integer;
  current_draft_revision integer;
  current_candidate_digest text;
  current_draft_status text;
BEGIN
  SELECT review.validation_id, review.candidate_digest, review.submitted_by, review.requires_four_eyes,
         review.draft_revision, draft.revision, draft.candidate_digest, draft.status
  INTO expected_validation_id, expected_candidate_digest, expected_submitter, expected_requires_four_eyes,
       expected_draft_revision, current_draft_revision, current_candidate_digest, current_draft_status
  FROM public.solution_profile_candidate_review review
  JOIN public.solution_profile_candidate_draft draft
    ON draft.scope_key = review.scope_key AND draft.draft_id = review.draft_id
  WHERE review.scope_key = NEW.scope_key AND review.review_id = NEW.review_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'solution profile candidate review was not found' USING ERRCODE = '23503';
  END IF;
  IF NEW.validation_id <> expected_validation_id OR NEW.candidate_digest <> expected_candidate_digest THEN
    RAISE EXCEPTION 'solution profile candidate review decision evidence does not match its review'
      USING ERRCODE = '23514';
  END IF;
  IF expected_requires_four_eyes
    AND lower(btrim(NEW.decided_by)) = lower(btrim(expected_submitter)) THEN
    RAISE EXCEPTION 'solution profile candidate review submitter cannot decide their own review'
      USING ERRCODE = '23514';
  END IF;
  IF current_draft_status <> 'draft'
    OR current_draft_revision <> expected_draft_revision
    OR current_candidate_digest <> expected_candidate_digest THEN
    RAISE EXCEPTION 'solution profile candidate review is superseded'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION public.reject_solution_profile_candidate_review_mutation()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  RAISE EXCEPTION 'solution profile candidate review evidence is immutable'
    USING ERRCODE = '55000';
END;
$$;

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_trigger
    WHERE tgname = 'trg_solution_profile_candidate_review_decision_binding'
      AND tgrelid = 'public.solution_profile_candidate_review_decision'::regclass
  ) THEN
    CREATE TRIGGER trg_solution_profile_candidate_review_decision_binding
      BEFORE INSERT ON public.solution_profile_candidate_review_decision
      FOR EACH ROW EXECUTE FUNCTION public.validate_solution_profile_candidate_review_decision();
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM pg_trigger
    WHERE tgname = 'trg_solution_profile_candidate_review_immutable'
      AND tgrelid = 'public.solution_profile_candidate_review'::regclass
  ) THEN
    CREATE TRIGGER trg_solution_profile_candidate_review_immutable
      BEFORE UPDATE OR DELETE ON public.solution_profile_candidate_review
      FOR EACH ROW EXECUTE FUNCTION public.reject_solution_profile_candidate_review_mutation();
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM pg_trigger
    WHERE tgname = 'trg_solution_profile_candidate_review_decision_immutable'
      AND tgrelid = 'public.solution_profile_candidate_review_decision'::regclass
  ) THEN
    CREATE TRIGGER trg_solution_profile_candidate_review_decision_immutable
      BEFORE UPDATE OR DELETE ON public.solution_profile_candidate_review_decision
      FOR EACH ROW EXECUTE FUNCTION public.reject_solution_profile_candidate_review_mutation();
  END IF;
END
$$;

-- Controller-owned immutable publication registry. A publication is accepted
-- only for the exact current validation carrying an approved four-eyes review.
CREATE TABLE IF NOT EXISTS public.platform_artifact_publication (
  publication_id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,
  artifact_kind text NOT NULL CHECK (artifact_kind IN ('domain-package', 'solution-profile')),
  artifact_id text NOT NULL,
  artifact_version text NOT NULL,
  artifact_digest text NOT NULL CHECK (artifact_digest ~ '^sha256:[0-9a-f]{64}$'),
  candidate_digest text NOT NULL CHECK (candidate_digest ~ '^sha256:[0-9a-f]{64}$'),
  artifact_json jsonb NOT NULL,
  scope_key text NOT NULL,
  review_id uuid NOT NULL,
  validation_id uuid NOT NULL,
  signed_evidence text NOT NULL,
  signing_key_id text NOT NULL,
  published_by text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (artifact_kind, artifact_id, artifact_version),
  CONSTRAINT chk_platform_artifact_publication_identity
    CHECK (length(btrim(artifact_id)) > 0 AND length(btrim(artifact_version)) > 0),
  CONSTRAINT chk_platform_artifact_publication_signer
    CHECK (length(btrim(signing_key_id)) > 0 AND length(btrim(published_by)) > 0)
);

CREATE INDEX IF NOT EXISTS idx_platform_artifact_publication_created
  ON public.platform_artifact_publication (created_at DESC, publication_id DESC);

CREATE OR REPLACE FUNCTION public.validate_platform_artifact_publication()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  approved boolean := false;
BEGIN
  IF NEW.artifact_kind = 'domain-package' THEN
    SELECT true INTO approved
    FROM public.platform_package_candidate_review review
    JOIN public.platform_package_candidate_review_decision decision
      ON decision.scope_key = review.scope_key AND decision.review_id = review.review_id
    JOIN public.platform_package_candidate_draft draft
      ON draft.scope_key = review.scope_key AND draft.draft_id = review.draft_id
    JOIN public.platform_package_candidate_validation validation
      ON validation.scope_key = review.scope_key AND validation.validation_id = review.validation_id
    WHERE review.scope_key = NEW.scope_key
      AND review.review_id = NEW.review_id
      AND review.validation_id = NEW.validation_id
      AND review.candidate_digest = NEW.candidate_digest
      AND review.package_id = NEW.artifact_id
      AND review.candidate_package_version = NEW.artifact_version
      AND decision.decision = 'approved'
      AND decision.validation_id = review.validation_id
      AND decision.candidate_digest = review.candidate_digest
      AND draft.status = 'draft'
      AND draft.revision = review.draft_revision
      AND draft.candidate_digest = review.candidate_digest
      AND validation.result_json #>> '{artifact,digest}' = NEW.artifact_digest;
  ELSE
    SELECT true INTO approved
    FROM public.solution_profile_candidate_review review
    JOIN public.solution_profile_candidate_review_decision decision
      ON decision.scope_key = review.scope_key AND decision.review_id = review.review_id
    JOIN public.solution_profile_candidate_draft draft
      ON draft.scope_key = review.scope_key AND draft.draft_id = review.draft_id
    JOIN public.solution_profile_candidate_validation validation
      ON validation.scope_key = review.scope_key AND validation.validation_id = review.validation_id
    WHERE review.scope_key = NEW.scope_key
      AND review.review_id = NEW.review_id
      AND review.validation_id = NEW.validation_id
      AND review.candidate_digest = NEW.candidate_digest
      AND review.profile_id = NEW.artifact_id
      AND review.candidate_profile_version = NEW.artifact_version
      AND decision.decision = 'approved'
      AND decision.validation_id = review.validation_id
      AND decision.candidate_digest = review.candidate_digest
      AND draft.status = 'draft'
      AND draft.revision = review.draft_revision
      AND draft.candidate_digest = review.candidate_digest
      AND validation.candidate_digest = NEW.artifact_digest;
  END IF;
  IF NOT approved THEN
    RAISE EXCEPTION 'artifact publication requires a current exact approved review'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION public.reject_platform_artifact_publication_mutation()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  RAISE EXCEPTION 'published platform artifacts are immutable' USING ERRCODE = '55000';
END;
$$;

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_trigger
    WHERE tgname = 'trg_platform_artifact_publication_binding'
      AND tgrelid = 'public.platform_artifact_publication'::regclass
  ) THEN
    CREATE TRIGGER trg_platform_artifact_publication_binding
      BEFORE INSERT ON public.platform_artifact_publication
      FOR EACH ROW EXECUTE FUNCTION public.validate_platform_artifact_publication();
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM pg_trigger
    WHERE tgname = 'trg_platform_artifact_publication_immutable'
      AND tgrelid = 'public.platform_artifact_publication'::regclass
  ) THEN
    CREATE TRIGGER trg_platform_artifact_publication_immutable
      BEFORE UPDATE OR DELETE ON public.platform_artifact_publication
      FOR EACH ROW EXECUTE FUNCTION public.reject_platform_artifact_publication_mutation();
  END IF;
END
$$;

-- Exact historical solution-profile bytes retained only for recovering an
-- installed package set whose profile is no longer in the current catalog.
-- The artifact is append-only and does not activate or mutate packages.
CREATE TABLE IF NOT EXISTS public.recovered_solution_profile_artifact (
  scope_key text NOT NULL REFERENCES public.platform_tenant(scope_key) ON DELETE RESTRICT,
  profile_id text NOT NULL,
  profile_version text NOT NULL,
  profile_digest text NOT NULL,
  manifest_text text NOT NULL,
  manifest_json jsonb NOT NULL,
  package_set_digest text NOT NULL,
  recovered_by text NOT NULL,
  recovered_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (scope_key, profile_id, profile_digest),
  CONSTRAINT chk_recovered_solution_profile_identity
    CHECK (length(btrim(profile_id)) > 0 AND length(btrim(profile_version)) > 0),
  CONSTRAINT chk_recovered_solution_profile_digest
    CHECK (profile_digest ~ '^sha256:[0-9a-f]{64}$'),
  CONSTRAINT chk_recovered_solution_profile_package_set_digest
    CHECK (package_set_digest ~ '^sha256:[0-9a-f]{64}$'),
  CONSTRAINT chk_recovered_solution_profile_actor
    CHECK (length(btrim(recovered_by)) > 0)
);

CREATE INDEX IF NOT EXISTS idx_recovered_solution_profile_artifact_time
  ON public.recovered_solution_profile_artifact (scope_key, recovered_at DESC);

CREATE OR REPLACE FUNCTION public.reject_recovered_solution_profile_artifact_mutation()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  RAISE EXCEPTION 'recovered solution-profile artifacts are immutable'
    USING ERRCODE = '55000';
END;
$$;

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_trigger
    WHERE tgname = 'trg_recovered_solution_profile_artifact_immutable'
      AND tgrelid = 'public.recovered_solution_profile_artifact'::regclass
  ) THEN
    CREATE TRIGGER trg_recovered_solution_profile_artifact_immutable
      BEFORE UPDATE OR DELETE ON public.recovered_solution_profile_artifact
      FOR EACH ROW EXECUTE FUNCTION public.reject_recovered_solution_profile_artifact_mutation();
  END IF;
END
$$;

-- P2.5 compatibility migration: the 1.x setup path had one implicit
-- controller scope. Preserve its data under the explicit default tenant before
-- tenant and activation foreign keys are validated.
UPDATE public.platform_package_installation
SET scope_key = 'tenant:default'
WHERE scope_key = 'controller:default';

UPDATE public.platform_package_definition_ownership
SET scope_key = 'tenant:default'
WHERE scope_key = 'controller:default';

UPDATE public.platform_semantic_definition_overlay
SET scope_key = 'tenant:default'
WHERE scope_key = 'controller:default';

UPDATE public.platform_package_audit
SET scope_key = 'tenant:default'
WHERE scope_key = 'controller:default';

INSERT INTO public.platform_tenant (scope_key, display_name)
SELECT scope_key, scope_key
FROM (
  SELECT scope_key FROM public.platform_package_installation
  UNION
  SELECT scope_key FROM public.platform_package_definition_ownership
  UNION
  SELECT scope_key FROM public.platform_semantic_definition_overlay
  UNION
  SELECT scope_key FROM public.platform_package_audit
) existing_scopes
ON CONFLICT (scope_key) DO NOTHING;

ALTER TABLE public.platform_package_definition_ownership
  DROP CONSTRAINT IF EXISTS fk_platform_package_definition_ownership_installation;

ALTER TABLE public.platform_semantic_definition_overlay
  DROP CONSTRAINT IF EXISTS fk_platform_semantic_definition_overlay_installation;

ALTER TABLE public.platform_package_installation
  DROP CONSTRAINT IF EXISTS uq_platform_package_installation_exact_version;

ALTER TABLE public.platform_package_installation
  ADD CONSTRAINT uq_platform_package_installation_exact_version
  UNIQUE (scope_key, package_id, package_version);

ALTER TABLE public.platform_package_installation
  DROP CONSTRAINT IF EXISTS fk_platform_package_installation_tenant;

ALTER TABLE public.platform_package_installation
  ADD CONSTRAINT fk_platform_package_installation_tenant
  FOREIGN KEY (scope_key)
  REFERENCES public.platform_tenant(scope_key) ON DELETE RESTRICT
  NOT VALID;

ALTER TABLE public.platform_package_installation
  VALIDATE CONSTRAINT fk_platform_package_installation_tenant;

ALTER TABLE public.platform_package_definition_ownership
  ADD CONSTRAINT fk_platform_package_definition_ownership_installation
  FOREIGN KEY (scope_key, package_id, package_version)
  REFERENCES public.platform_package_installation(scope_key, package_id, package_version)
  ON DELETE RESTRICT DEFERRABLE INITIALLY DEFERRED
  NOT VALID;

ALTER TABLE public.platform_package_definition_ownership
  VALIDATE CONSTRAINT fk_platform_package_definition_ownership_installation;

ALTER TABLE public.platform_semantic_definition_overlay
  ADD CONSTRAINT fk_platform_semantic_definition_overlay_installation
  FOREIGN KEY (scope_key, base_package_id, base_package_version)
  REFERENCES public.platform_package_installation(scope_key, package_id, package_version)
  ON DELETE RESTRICT DEFERRABLE INITIALLY DEFERRED
  NOT VALID;

ALTER TABLE public.platform_semantic_definition_overlay
  VALIDATE CONSTRAINT fk_platform_semantic_definition_overlay_installation;

ALTER TABLE public.platform_package_audit
  DROP CONSTRAINT IF EXISTS fk_platform_package_audit_tenant;

ALTER TABLE public.platform_package_audit
  ADD CONSTRAINT fk_platform_package_audit_tenant
  FOREIGN KEY (scope_key)
  REFERENCES public.platform_tenant(scope_key) ON DELETE RESTRICT
  NOT VALID;

ALTER TABLE public.platform_package_audit
  VALIDATE CONSTRAINT fk_platform_package_audit_tenant;

-- === OPENHUB PROVIDER ADD-ON CATALOG ======================================
-- Executable providers are cataloged separately from declarative domain
-- packages. A provider id/version is immutable by artifact digest. Tenant
-- installation state references an exact reviewed catalog artifact and cannot
-- enter an active runtime state without recorded permission review evidence.
CREATE TABLE IF NOT EXISTS public.provider_addon (
  id text PRIMARY KEY,
  package_name text NOT NULL,
  display_name text NOT NULL,
  description text NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT chk_provider_addon_id
    CHECK (id ~ '^[a-z][a-z0-9]*(?:[.-][a-z0-9]+)+$'),
  CONSTRAINT chk_provider_addon_package_name
    CHECK (length(btrim(package_name)) > 0),
  CONSTRAINT chk_provider_addon_display_name
    CHECK (length(btrim(display_name)) > 0)
);

CREATE TABLE IF NOT EXISTS public.provider_addon_version (
  provider_id text NOT NULL,
  version text NOT NULL,
  artifact_digest text NOT NULL,
  manifest_json jsonb NOT NULL,
  controller_compatibility text NOT NULL,
  provider_api text NOT NULL,
  configuration_schema_path text NOT NULL,
  configuration_schema_digest text NOT NULL,
  configuration_schema_json jsonb NOT NULL,
  content_size_bytes bigint NOT NULL,
  reviewed_by text NOT NULL,
  reviewed_at timestamptz NOT NULL DEFAULT now(),
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (provider_id, version),
  UNIQUE (provider_id, version, artifact_digest),
  CONSTRAINT fk_provider_addon_version_provider
    FOREIGN KEY (provider_id) REFERENCES public.provider_addon(id) ON DELETE CASCADE,
  CONSTRAINT chk_provider_addon_version_digest
    CHECK (artifact_digest ~ '^sha256:[0-9a-f]{64}$'),
  CONSTRAINT chk_provider_addon_version_config_digest
    CHECK (configuration_schema_digest ~ '^sha256:[0-9a-f]{64}$'),
  CONSTRAINT chk_provider_addon_version_provider_api
    CHECK (provider_api ~ '^[1-9][0-9]*$'),
  CONSTRAINT chk_provider_addon_version_manifest_json
    CHECK (jsonb_typeof(manifest_json) = 'object'),
  CONSTRAINT chk_provider_addon_version_config_json
    CHECK (jsonb_typeof(configuration_schema_json) = 'object'),
  CONSTRAINT chk_provider_addon_version_size
    CHECK (content_size_bytes >= 0),
  CONSTRAINT chk_provider_addon_version_reviewer
    CHECK (length(btrim(reviewed_by)) > 0)
);

CREATE TABLE IF NOT EXISTS public.provider_addon_source_lock (
  provider_id text NOT NULL,
  provider_version text NOT NULL,
  artifact_digest text NOT NULL,
  source_kind text NOT NULL,
  lock_digest text NOT NULL,
  lock_json jsonb NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (provider_id, provider_version),
  CONSTRAINT fk_provider_addon_source_lock_version
    FOREIGN KEY (provider_id, provider_version, artifact_digest)
    REFERENCES public.provider_addon_version(provider_id, version, artifact_digest) ON DELETE CASCADE,
  CONSTRAINT chk_provider_addon_source_lock_kind
    CHECK (source_kind IN ('repository', 'offline', 'oci')),
  CONSTRAINT chk_provider_addon_source_lock_artifact_digest
    CHECK (artifact_digest ~ '^sha256:[0-9a-f]{64}$'),
  CONSTRAINT chk_provider_addon_source_lock_digest
    CHECK (lock_digest ~ '^sha256:[0-9a-f]{64}$'),
  CONSTRAINT chk_provider_addon_source_lock_json
    CHECK (jsonb_typeof(lock_json) = 'object')
);

CREATE OR REPLACE FUNCTION public.reject_provider_addon_source_lock_mutation()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  RAISE EXCEPTION 'provider add-on source locks are immutable'
    USING ERRCODE = '55000';
END
$$;

DROP TRIGGER IF EXISTS trg_provider_addon_source_lock_immutable
  ON public.provider_addon_source_lock;
CREATE TRIGGER trg_provider_addon_source_lock_immutable
  BEFORE UPDATE OR DELETE ON public.provider_addon_source_lock
  FOR EACH ROW EXECUTE FUNCTION public.reject_provider_addon_source_lock_mutation();

CREATE TABLE IF NOT EXISTS public.provider_addon_capability (
  provider_id text NOT NULL,
  provider_version text NOT NULL,
  capability_id text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (provider_id, provider_version, capability_id),
  CONSTRAINT fk_provider_addon_capability_version
    FOREIGN KEY (provider_id, provider_version)
    REFERENCES public.provider_addon_version(provider_id, version) ON DELETE CASCADE,
  CONSTRAINT chk_provider_addon_capability_id
    CHECK (capability_id ~ '^[a-z][a-z0-9]*(?:[.-][a-z0-9]+)+$')
);

CREATE INDEX IF NOT EXISTS idx_provider_addon_capability_lookup
  ON public.provider_addon_capability (capability_id, provider_id, provider_version);

CREATE TABLE IF NOT EXISTS public.provider_addon_permission_requirement (
  provider_id text NOT NULL,
  provider_version text NOT NULL,
  permission_id text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (provider_id, provider_version, permission_id),
  CONSTRAINT fk_provider_addon_permission_version
    FOREIGN KEY (provider_id, provider_version)
    REFERENCES public.provider_addon_version(provider_id, version) ON DELETE CASCADE,
  CONSTRAINT chk_provider_addon_permission_id
    CHECK (permission_id ~ '^[a-z][a-z0-9]*(?:[.-][a-z0-9]+)+$')
);

CREATE TABLE IF NOT EXISTS public.provider_addon_installation (
  scope_key text NOT NULL,
  provider_id text NOT NULL,
  provider_version text NOT NULL,
  artifact_digest text NOT NULL,
  status text NOT NULL DEFAULT 'planned',
  permission_review_json jsonb NOT NULL DEFAULT '[]'::jsonb,
  permission_reviewed_by text NULL,
  permission_reviewed_at timestamptz NULL,
  installed_by text NULL,
  installed_at timestamptz NULL,
  updated_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (scope_key, provider_id),
  CONSTRAINT fk_provider_addon_installation_tenant
    FOREIGN KEY (scope_key)
    REFERENCES public.platform_tenant(scope_key) ON DELETE RESTRICT,
  CONSTRAINT fk_provider_addon_installation_version
    FOREIGN KEY (provider_id, provider_version, artifact_digest)
    REFERENCES public.provider_addon_version(provider_id, version, artifact_digest) ON DELETE RESTRICT,
  CONSTRAINT chk_provider_addon_installation_status
    CHECK (status IN ('planned', 'installed', 'stopped', 'failed', 'removed')),
  CONSTRAINT chk_provider_addon_installation_digest
    CHECK (artifact_digest ~ '^sha256:[0-9a-f]{64}$'),
  CONSTRAINT chk_provider_addon_installation_review_json
    CHECK (jsonb_typeof(permission_review_json) = 'array'),
  CONSTRAINT chk_provider_addon_installation_review_pair
    CHECK (
      (permission_reviewed_by IS NULL AND permission_reviewed_at IS NULL)
      OR (length(btrim(permission_reviewed_by)) > 0 AND permission_reviewed_at IS NOT NULL)
    ),
  CONSTRAINT chk_provider_addon_installation_active_review
    CHECK (
      status NOT IN ('installed', 'stopped')
      OR (permission_reviewed_by IS NOT NULL AND permission_reviewed_at IS NOT NULL)
    )
);

CREATE INDEX IF NOT EXISTS idx_provider_addon_installation_status
  ON public.provider_addon_installation (scope_key, status, provider_id);

CREATE UNIQUE INDEX IF NOT EXISTS uq_provider_addon_installation_exact_artifact
  ON public.provider_addon_installation
    (scope_key, provider_id, provider_version, artifact_digest);

-- Provider runtimes receive an opaque controller-owned process namespace and
-- filesystem isolation key. The binding is immutable: lifecycle operations
-- can stop or remove only this exact tenant/provider/artifact unit and must not
-- accept a provider-supplied path or process name.
CREATE TABLE IF NOT EXISTS public.provider_addon_runtime_binding (
  scope_key text NOT NULL,
  provider_id text NOT NULL,
  provider_version text NOT NULL,
  artifact_digest text NOT NULL,
  runtime_unit_id text NOT NULL,
  process_name text NOT NULL,
  isolation_key text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (scope_key, provider_id),
  UNIQUE (runtime_unit_id),
  UNIQUE (process_name),
  UNIQUE (isolation_key),
  CONSTRAINT fk_provider_addon_runtime_binding_installation
    FOREIGN KEY (scope_key, provider_id, provider_version, artifact_digest)
    REFERENCES public.provider_addon_installation
      (scope_key, provider_id, provider_version, artifact_digest) ON DELETE RESTRICT,
  CONSTRAINT chk_provider_addon_runtime_binding_unit
    CHECK (runtime_unit_id ~ '^provider-runtime:[0-9a-f]{64}$'),
  CONSTRAINT chk_provider_addon_runtime_binding_process
    CHECK (process_name ~ '^openhub-provider-[0-9a-f]{32}$'),
  CONSTRAINT chk_provider_addon_runtime_binding_isolation
    CHECK (isolation_key ~ '^[0-9a-f]{64}$')
);

CREATE OR REPLACE FUNCTION public.reject_provider_addon_runtime_binding_mutation()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  RAISE EXCEPTION 'provider add-on runtime bindings are immutable'
    USING ERRCODE = '55000';
END
$$;

DROP TRIGGER IF EXISTS trg_provider_addon_runtime_binding_immutable
  ON public.provider_addon_runtime_binding;
CREATE TRIGGER trg_provider_addon_runtime_binding_immutable
  BEFORE UPDATE OR DELETE ON public.provider_addon_runtime_binding
  FOR EACH ROW EXECUTE FUNCTION public.reject_provider_addon_runtime_binding_mutation();

CREATE TABLE IF NOT EXISTS public.provider_addon_permission_review (
  scope_key text NOT NULL,
  provider_id text NOT NULL,
  provider_version text NOT NULL,
  artifact_digest text NOT NULL,
  plan_digest text NOT NULL,
  permission_set_digest text NOT NULL,
  permissions_json jsonb NOT NULL,
  reviewed_by text NOT NULL,
  reviewed_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (scope_key, provider_id, plan_digest),
  UNIQUE (scope_key, provider_id, provider_version, artifact_digest, plan_digest),
  CONSTRAINT fk_provider_addon_permission_review_tenant
    FOREIGN KEY (scope_key)
    REFERENCES public.platform_tenant(scope_key) ON DELETE RESTRICT,
  CONSTRAINT fk_provider_addon_permission_review_version
    FOREIGN KEY (provider_id, provider_version, artifact_digest)
    REFERENCES public.provider_addon_version(provider_id, version, artifact_digest) ON DELETE RESTRICT,
  CONSTRAINT chk_provider_addon_permission_review_plan_digest
    CHECK (plan_digest ~ '^sha256:[0-9a-f]{64}$'),
  CONSTRAINT chk_provider_addon_permission_review_set_digest
    CHECK (permission_set_digest ~ '^sha256:[0-9a-f]{64}$'),
  CONSTRAINT chk_provider_addon_permission_review_json
    CHECK (jsonb_typeof(permissions_json) = 'array'),
  CONSTRAINT chk_provider_addon_permission_review_actor
    CHECK (length(btrim(reviewed_by)) > 0)
);

CREATE TABLE IF NOT EXISTS public.provider_addon_operation (
  scope_key text NOT NULL,
  operation_id uuid NOT NULL,
  operation_kind text NOT NULL,
  provider_id text NOT NULL,
  provider_version text NOT NULL,
  artifact_digest text NOT NULL,
  request_digest text NOT NULL,
  result_json jsonb NOT NULL,
  changed_by text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (scope_key, operation_id),
  CONSTRAINT fk_provider_addon_operation_tenant
    FOREIGN KEY (scope_key)
    REFERENCES public.platform_tenant(scope_key) ON DELETE RESTRICT,
  CONSTRAINT fk_provider_addon_operation_version
    FOREIGN KEY (provider_id, provider_version, artifact_digest)
    REFERENCES public.provider_addon_version(provider_id, version, artifact_digest) ON DELETE RESTRICT,
  CONSTRAINT chk_provider_addon_operation_kind
    CHECK (operation_kind IN (
      'permission_review', 'credential_issue', 'lifecycle_stop', 'lifecycle_remove'
    )),
  CONSTRAINT chk_provider_addon_operation_request_digest
    CHECK (request_digest ~ '^sha256:[0-9a-f]{64}$'),
  CONSTRAINT chk_provider_addon_operation_result_json
    CHECK (jsonb_typeof(result_json) = 'object'),
  CONSTRAINT chk_provider_addon_operation_actor
    CHECK (length(btrim(changed_by)) > 0)
);

-- CREATE TABLE IF NOT EXISTS does not evolve an existing P4.4 constraint.
-- Recreate only the operation-kind check so upgrades accept the two P4.8
-- lifecycle receipts while preserving every immutable operation row.
ALTER TABLE public.provider_addon_operation
  DROP CONSTRAINT IF EXISTS chk_provider_addon_operation_kind;
ALTER TABLE public.provider_addon_operation
  ADD CONSTRAINT chk_provider_addon_operation_kind
  CHECK (operation_kind IN (
    'permission_review', 'credential_issue', 'lifecycle_stop', 'lifecycle_remove'
  ));

CREATE OR REPLACE FUNCTION public.reject_provider_addon_immutable_evidence_mutation()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  RAISE EXCEPTION 'provider add-on review and operation evidence is immutable'
    USING ERRCODE = '55000';
END
$$;

DROP TRIGGER IF EXISTS trg_provider_addon_permission_review_immutable
  ON public.provider_addon_permission_review;
CREATE TRIGGER trg_provider_addon_permission_review_immutable
  BEFORE UPDATE OR DELETE ON public.provider_addon_permission_review
  FOR EACH ROW EXECUTE FUNCTION public.reject_provider_addon_immutable_evidence_mutation();

DROP TRIGGER IF EXISTS trg_provider_addon_operation_immutable
  ON public.provider_addon_operation;
CREATE TRIGGER trg_provider_addon_operation_immutable
  BEFORE UPDATE OR DELETE ON public.provider_addon_operation
  FOR EACH ROW EXECUTE FUNCTION public.reject_provider_addon_immutable_evidence_mutation();

CREATE TABLE IF NOT EXISTS public.provider_addon_service_credential (
  credential_id uuid PRIMARY KEY,
  credential_reference text NOT NULL UNIQUE,
  scope_key text NOT NULL,
  provider_id text NOT NULL,
  provider_version text NOT NULL,
  artifact_digest text NOT NULL,
  plan_digest text NOT NULL,
  token_hash text NOT NULL UNIQUE,
  permission_set_digest text NOT NULL,
  permissions_json jsonb NOT NULL,
  issued_by text NOT NULL,
  issued_at timestamptz NOT NULL DEFAULT now(),
  expires_at timestamptz NOT NULL,
  revoked_by text NULL,
  revoked_at timestamptz NULL,
  CONSTRAINT fk_provider_addon_service_credential_review
    FOREIGN KEY (scope_key, provider_id, provider_version, artifact_digest, plan_digest)
    REFERENCES public.provider_addon_permission_review
      (scope_key, provider_id, provider_version, artifact_digest, plan_digest) ON DELETE RESTRICT,
  CONSTRAINT chk_provider_addon_service_credential_reference
    CHECK (credential_reference ~ '^provider-credential:[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'),
  CONSTRAINT chk_provider_addon_service_credential_hash
    CHECK (token_hash ~ '^sha256:[0-9a-f]{64}$'),
  CONSTRAINT chk_provider_addon_service_credential_set_digest
    CHECK (permission_set_digest ~ '^sha256:[0-9a-f]{64}$'),
  CONSTRAINT chk_provider_addon_service_credential_permissions
    CHECK (jsonb_typeof(permissions_json) = 'array'),
  CONSTRAINT chk_provider_addon_service_credential_actor
    CHECK (length(btrim(issued_by)) > 0),
  CONSTRAINT chk_provider_addon_service_credential_expiry
    CHECK (expires_at > issued_at),
  CONSTRAINT chk_provider_addon_service_credential_revocation_pair
    CHECK (
      (revoked_by IS NULL AND revoked_at IS NULL)
      OR (length(btrim(revoked_by)) > 0 AND revoked_at IS NOT NULL)
    )
);

CREATE INDEX IF NOT EXISTS idx_provider_addon_service_credential_active
  ON public.provider_addon_service_credential (scope_key, provider_id, expires_at)
  WHERE revoked_at IS NULL;

CREATE TABLE IF NOT EXISTS public.provider_addon_audit (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  scope_key text NULL,
  provider_id text NOT NULL,
  provider_version text NOT NULL,
  artifact_digest text NOT NULL,
  event_type text NOT NULL,
  changed_by text NOT NULL,
  details_json jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT fk_provider_addon_audit_tenant
    FOREIGN KEY (scope_key) REFERENCES public.platform_tenant(scope_key) ON DELETE RESTRICT,
  CONSTRAINT fk_provider_addon_audit_version
    FOREIGN KEY (provider_id, provider_version, artifact_digest)
    REFERENCES public.provider_addon_version(provider_id, version, artifact_digest) ON DELETE RESTRICT,
  CONSTRAINT chk_provider_addon_audit_digest
    CHECK (artifact_digest ~ '^sha256:[0-9a-f]{64}$'),
  CONSTRAINT chk_provider_addon_audit_actor
    CHECK (length(btrim(changed_by)) > 0),
  CONSTRAINT chk_provider_addon_audit_details
    CHECK (jsonb_typeof(details_json) = 'object')
);

CREATE INDEX IF NOT EXISTS idx_provider_addon_audit_provider_created_at
  ON public.provider_addon_audit (provider_id, provider_version, created_at DESC);

CREATE INDEX IF NOT EXISTS idx_provider_addon_audit_scope_created_at
  ON public.provider_addon_audit (scope_key, created_at DESC)
  WHERE scope_key IS NOT NULL;

-- === OPENHUB STABLE ENTITY AND PLACEMENT FOUNDATION ========================
-- Phase 3 begins additively: canonical entity identity is independent from
-- namespace placement, while uns_object remains the active 1.x compatibility
-- representation until a later reviewed backfill and dual-write slice.
CREATE TABLE IF NOT EXISTS public.entity (
  stable_entity_id uuid PRIMARY KEY,
  scope_key text NOT NULL,
  entity_type_key text NOT NULL,
  display_name text NULL,
  status text NOT NULL DEFAULT 'active',
  identity_source text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (scope_key, stable_entity_id),
  FOREIGN KEY (scope_key)
    REFERENCES public.platform_tenant(scope_key) ON DELETE RESTRICT,
  CONSTRAINT chk_entity_type_key
    CHECK (entity_type_key ~ '^[a-z0-9]+(-[a-z0-9]+)*(\.[a-z0-9]+(-[a-z0-9]+)*)+$'),
  CONSTRAINT chk_entity_status
    CHECK (status IN ('active', 'archived', 'superseded')),
  CONSTRAINT chk_entity_identity_source
    CHECK (length(btrim(identity_source)) > 0)
);

CREATE INDEX IF NOT EXISTS idx_entity_scope_type_status
  ON public.entity (scope_key, entity_type_key, status);

CREATE TABLE IF NOT EXISTS public.entity_external_identity (
  external_identity_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  scope_key text NOT NULL,
  stable_entity_id uuid NOT NULL,
  provider_id text NOT NULL,
  external_system text NOT NULL,
  external_type text NOT NULL,
  external_id text NOT NULL,
  evidence_json jsonb NOT NULL DEFAULT '{}'::jsonb,
  verified_at timestamptz NULL,
  status text NOT NULL DEFAULT 'active',
  registration_source text NOT NULL DEFAULT 'legacy',
  reviewed_by text NULL,
  reviewed_at timestamptz NULL,
  review_evidence_json jsonb NOT NULL DEFAULT '{}'::jsonb,
  revoked_by text NULL,
  revoked_at timestamptz NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (scope_key, provider_id, external_system, external_type, external_id),
  FOREIGN KEY (scope_key)
    REFERENCES public.platform_tenant(scope_key) ON DELETE RESTRICT,
  FOREIGN KEY (scope_key, stable_entity_id)
    REFERENCES public.entity(scope_key, stable_entity_id) ON DELETE RESTRICT,
  CONSTRAINT chk_entity_external_identity_provider
    CHECK (length(btrim(provider_id)) > 0),
  CONSTRAINT chk_entity_external_identity_system
    CHECK (length(btrim(external_system)) > 0),
  CONSTRAINT chk_entity_external_identity_type
    CHECK (length(btrim(external_type)) > 0),
  CONSTRAINT chk_entity_external_identity_value
    CHECK (length(btrim(external_id)) > 0),
  CONSTRAINT chk_entity_external_identity_status
    CHECK (status IN ('active', 'revoked')),
  CONSTRAINT chk_entity_external_identity_review_pair
    CHECK ((reviewed_by IS NULL) = (reviewed_at IS NULL)),
  CONSTRAINT chk_entity_external_identity_review_source
    CHECK (length(btrim(registration_source)) > 0
      AND (registration_source <> 'admin-reviewed-provider'
        OR (reviewed_by IS NOT NULL AND reviewed_at IS NOT NULL))),
  CONSTRAINT chk_entity_external_identity_revocation_state
    CHECK ((status = 'active' AND revoked_by IS NULL AND revoked_at IS NULL)
      OR (status = 'revoked' AND revoked_by IS NOT NULL AND revoked_at IS NOT NULL))
);

CREATE INDEX IF NOT EXISTS idx_entity_external_identity_entity
  ON public.entity_external_identity (scope_key, stable_entity_id);

CREATE TABLE IF NOT EXISTS public.entity_external_identity_namespace (
  scope_key text NOT NULL,
  provider_id text NOT NULL,
  external_system text NOT NULL,
  external_type text NOT NULL,
  status text NOT NULL DEFAULT 'active',
  allow_auto_reconcile boolean NOT NULL DEFAULT false,
  reviewed_by text NOT NULL,
  reviewed_at timestamptz NOT NULL DEFAULT now(),
  evidence_json jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (scope_key, provider_id, external_system, external_type),
  FOREIGN KEY (scope_key)
    REFERENCES public.platform_tenant(scope_key) ON DELETE RESTRICT,
  CONSTRAINT chk_entity_external_identity_namespace_provider
    CHECK (provider_id ~ '^[a-z0-9]+([._-][a-z0-9]+)*$'),
  CONSTRAINT chk_entity_external_identity_namespace_system
    CHECK (external_system ~ '^[a-z0-9]+([._-][a-z0-9]+)*$'),
  CONSTRAINT chk_entity_external_identity_namespace_type
    CHECK (external_type ~ '^[a-z0-9]+([._-][a-z0-9]+)*$'),
  CONSTRAINT chk_entity_external_identity_namespace_status
    CHECK (status IN ('active', 'revoked')),
  CONSTRAINT chk_entity_external_identity_namespace_actor
    CHECK (length(btrim(reviewed_by)) > 0)
);

CREATE TABLE IF NOT EXISTS public.entity_external_identity_namespace_review (
  review_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  scope_key text NOT NULL,
  provider_id text NOT NULL,
  external_system text NOT NULL,
  external_type text NOT NULL,
  status text NOT NULL,
  allow_auto_reconcile boolean NOT NULL DEFAULT false,
  reviewed_by text NOT NULL,
  reviewed_at timestamptz NOT NULL,
  evidence_json jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY (scope_key, provider_id, external_system, external_type)
    REFERENCES public.entity_external_identity_namespace
      (scope_key, provider_id, external_system, external_type) ON DELETE RESTRICT,
  CONSTRAINT chk_entity_external_identity_namespace_review_status
    CHECK (status IN ('active', 'revoked')),
  CONSTRAINT chk_entity_external_identity_namespace_review_actor
    CHECK (length(btrim(reviewed_by)) > 0)
);

CREATE INDEX IF NOT EXISTS idx_entity_external_identity_namespace_review_time
  ON public.entity_external_identity_namespace_review
    (scope_key, provider_id, reviewed_at DESC);

CREATE TABLE IF NOT EXISTS public.asset_identity_provider_candidate_evidence (
  evidence_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  scope_key text NOT NULL,
  uns_object_id integer NOT NULL,
  source_workload_identity_id uuid NULL,
  provider_id text NOT NULL,
  external_system text NOT NULL,
  external_type text NOT NULL,
  external_id text NOT NULL,
  candidate_asset_path text NOT NULL,
  source_event_at timestamptz NULL,
  first_observed_at timestamptz NOT NULL DEFAULT now(),
  last_observed_at timestamptz NOT NULL DEFAULT now(),
  occurrence_count integer NOT NULL DEFAULT 1,
  evidence_digest text NOT NULL,
  evidence_json jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (scope_key, uns_object_id, provider_id, external_system, external_type,
          external_id, source_workload_identity_id),
  FOREIGN KEY (scope_key) REFERENCES public.platform_tenant(scope_key) ON DELETE RESTRICT,
  FOREIGN KEY (uns_object_id) REFERENCES public.uns_object(id) ON DELETE CASCADE,
  FOREIGN KEY (source_workload_identity_id)
    REFERENCES public.auth_workload_identities(id) ON DELETE SET NULL,
  FOREIGN KEY (scope_key, provider_id, external_system, external_type)
    REFERENCES public.entity_external_identity_namespace
      (scope_key, provider_id, external_system, external_type) ON DELETE RESTRICT,
  CONSTRAINT chk_asset_identity_provider_candidate_path
    CHECK (length(btrim(candidate_asset_path)) > 0
      AND candidate_asset_path = btrim(candidate_asset_path)
      AND candidate_asset_path !~ '(^/|/$|//|[+#])'),
  CONSTRAINT chk_asset_identity_provider_candidate_external_id
    CHECK (length(btrim(external_id)) > 0),
  CONSTRAINT chk_asset_identity_provider_candidate_count
    CHECK (occurrence_count > 0),
  CONSTRAINT chk_asset_identity_provider_candidate_digest
    CHECK (evidence_digest ~ '^sha256:[0-9a-f]{64}$')
);

CREATE INDEX IF NOT EXISTS idx_asset_identity_provider_candidate_pair
  ON public.asset_identity_provider_candidate_evidence
    (scope_key, provider_id, external_system, external_type, external_id, last_observed_at DESC);

CREATE INDEX IF NOT EXISTS idx_asset_identity_provider_candidate_workload
  ON public.asset_identity_provider_candidate_evidence
    (source_workload_identity_id, last_observed_at DESC);

CREATE TABLE IF NOT EXISTS public.entity_external_identity_conflict (
  conflict_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  scope_key text NOT NULL,
  provider_id text NOT NULL,
  external_system text NOT NULL,
  external_type text NOT NULL,
  external_id text NOT NULL,
  existing_external_identity_id uuid NOT NULL,
  existing_stable_entity_id uuid NOT NULL,
  candidate_stable_entity_id uuid NOT NULL,
  existing_status text NOT NULL,
  state text NOT NULL DEFAULT 'pending',
  decision text NULL,
  occurrence_count integer NOT NULL DEFAULT 1,
  revision bigint NOT NULL DEFAULT 1,
  evidence_json jsonb NOT NULL DEFAULT '{}'::jsonb,
  requested_by text NOT NULL,
  first_seen_at timestamptz NOT NULL DEFAULT now(),
  last_seen_at timestamptz NOT NULL DEFAULT now(),
  reviewed_by text NULL,
  reviewed_at timestamptz NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (scope_key, provider_id, external_system, external_type, external_id,
          candidate_stable_entity_id),
  FOREIGN KEY (scope_key) REFERENCES public.platform_tenant(scope_key) ON DELETE RESTRICT,
  FOREIGN KEY (existing_external_identity_id)
    REFERENCES public.entity_external_identity(external_identity_id) ON DELETE RESTRICT,
  FOREIGN KEY (scope_key, existing_stable_entity_id)
    REFERENCES public.entity(scope_key, stable_entity_id) ON DELETE RESTRICT,
  FOREIGN KEY (scope_key, candidate_stable_entity_id)
    REFERENCES public.entity(scope_key, stable_entity_id) ON DELETE RESTRICT,
  CONSTRAINT chk_entity_external_identity_conflict_entities
    CHECK (existing_stable_entity_id <> candidate_stable_entity_id
      OR existing_status = 'revoked'),
  CONSTRAINT chk_entity_external_identity_conflict_status
    CHECK (existing_status IN ('active', 'revoked')),
  CONSTRAINT chk_entity_external_identity_conflict_state
    CHECK (state IN ('pending', 'resolved')),
  CONSTRAINT chk_entity_external_identity_conflict_decision
    CHECK ((state = 'pending' AND decision IS NULL AND reviewed_by IS NULL AND reviewed_at IS NULL)
      OR (state = 'resolved' AND decision = 'keep-existing'
        AND reviewed_by IS NOT NULL AND reviewed_at IS NOT NULL)),
  CONSTRAINT chk_entity_external_identity_conflict_counts
    CHECK (occurrence_count > 0 AND revision > 0),
  CONSTRAINT chk_entity_external_identity_conflict_requester
    CHECK (length(btrim(requested_by)) > 0)
);

CREATE INDEX IF NOT EXISTS idx_entity_external_identity_conflict_queue
  ON public.entity_external_identity_conflict (scope_key, state, last_seen_at DESC);

CREATE TABLE IF NOT EXISTS public.namespace_node (
  namespace_node_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  scope_key text NOT NULL,
  parent_namespace_node_id uuid NULL,
  segment text NOT NULL,
  full_path text NOT NULL,
  projection_kind text NOT NULL DEFAULT 'legacy_uns',
  status text NOT NULL DEFAULT 'active',
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (scope_key, namespace_node_id),
  UNIQUE (scope_key, full_path),
  FOREIGN KEY (scope_key)
    REFERENCES public.platform_tenant(scope_key) ON DELETE RESTRICT,
  FOREIGN KEY (scope_key, parent_namespace_node_id)
    REFERENCES public.namespace_node(scope_key, namespace_node_id) ON DELETE RESTRICT,
  CONSTRAINT chk_namespace_node_segment
    CHECK (length(btrim(segment)) > 0 AND position('/' IN segment) = 0),
  CONSTRAINT chk_namespace_node_full_path
    CHECK (
      length(btrim(full_path)) > 0
      AND full_path = btrim(full_path)
      AND full_path !~ '(^/|/$|//)'
    ),
  CONSTRAINT chk_namespace_node_projection_kind
    CHECK (projection_kind IN ('legacy_uns', 'provider', 'curated')),
  CONSTRAINT chk_namespace_node_status
    CHECK (status IN ('active', 'archived'))
);

CREATE INDEX IF NOT EXISTS idx_namespace_node_parent
  ON public.namespace_node (scope_key, parent_namespace_node_id);

CREATE TABLE IF NOT EXISTS public.entity_placement (
  placement_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  scope_key text NOT NULL,
  stable_entity_id uuid NOT NULL,
  namespace_node_id uuid NOT NULL,
  placement_kind text NOT NULL DEFAULT 'primary',
  valid_from timestamptz NOT NULL,
  valid_to timestamptz NULL,
  source text NOT NULL,
  evidence_json jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by text NULL,
  UNIQUE (scope_key, placement_id),
  FOREIGN KEY (scope_key)
    REFERENCES public.platform_tenant(scope_key) ON DELETE RESTRICT,
  FOREIGN KEY (scope_key, stable_entity_id)
    REFERENCES public.entity(scope_key, stable_entity_id) ON DELETE RESTRICT,
  FOREIGN KEY (scope_key, namespace_node_id)
    REFERENCES public.namespace_node(scope_key, namespace_node_id) ON DELETE RESTRICT,
  CONSTRAINT chk_entity_placement_kind
    CHECK (placement_kind IN ('primary', 'alias')),
  CONSTRAINT chk_entity_placement_interval
    CHECK (valid_to IS NULL OR valid_to > valid_from),
  CONSTRAINT chk_entity_placement_source
    CHECK (length(btrim(source)) > 0)
);

CREATE INDEX IF NOT EXISTS idx_entity_placement_entity_history
  ON public.entity_placement (scope_key, stable_entity_id, valid_from DESC, valid_to DESC NULLS FIRST);

CREATE INDEX IF NOT EXISTS idx_entity_placement_namespace_history
  ON public.entity_placement (scope_key, namespace_node_id, valid_from DESC, valid_to DESC NULLS FIRST);

CREATE UNIQUE INDEX IF NOT EXISTS uq_entity_placement_current_primary_entity
  ON public.entity_placement (scope_key, stable_entity_id)
  WHERE valid_to IS NULL AND placement_kind = 'primary';

CREATE UNIQUE INDEX IF NOT EXISTS uq_entity_placement_current_primary_namespace
  ON public.entity_placement (scope_key, namespace_node_id)
  WHERE valid_to IS NULL AND placement_kind = 'primary';

-- Stable entity observation ownership is separate from namespace placement.
-- These tables are additive; MQTT identity claims are enabled only in a later
-- feature-gated controller slice.
CREATE SEQUENCE IF NOT EXISTS public.entity_observation_binding_revision_seq AS bigint;

CREATE TABLE IF NOT EXISTS public.entity_observation_binding (
  observation_binding_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  scope_key text NOT NULL,
  stable_entity_id uuid NOT NULL,
  binding_kind text NOT NULL,
  topic_path text NOT NULL,
  source_workload_identity_id uuid NULL,
  source_authority text NOT NULL,
  source_priority integer NOT NULL DEFAULT 100,
  resolution_basis text NOT NULL,
  time_basis text NOT NULL,
  valid_from timestamptz NOT NULL,
  valid_to timestamptz NULL,
  revision bigint NOT NULL DEFAULT nextval('public.entity_observation_binding_revision_seq'),
  binding_digest text NOT NULL,
  evidence_json jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by text NULL,
  UNIQUE (scope_key, observation_binding_id),
  FOREIGN KEY (scope_key) REFERENCES public.platform_tenant(scope_key) ON DELETE RESTRICT,
  FOREIGN KEY (scope_key, stable_entity_id)
    REFERENCES public.entity(scope_key, stable_entity_id) ON DELETE RESTRICT,
  FOREIGN KEY (source_workload_identity_id)
    REFERENCES public.auth_workload_identities("id") ON DELETE RESTRICT,
  CONSTRAINT chk_entity_observation_binding_kind
    CHECK (binding_kind IN ('asset-prefix', 'attribute-topic')),
  CONSTRAINT chk_entity_observation_binding_topic
    CHECK (length(btrim(topic_path)) > 0 AND topic_path = btrim(topic_path)
      AND topic_path !~ '(^/|/$|//)' AND topic_path !~ '[+#]'),
  CONSTRAINT chk_entity_observation_binding_authority
    CHECK (source_authority IN ('transport-authenticated', 'reviewed-import', 'controller-legacy')),
  CONSTRAINT chk_entity_observation_binding_source_identity
    CHECK (source_workload_identity_id IS NOT NULL OR source_authority = 'controller-legacy'),
  CONSTRAINT chk_entity_observation_binding_priority CHECK (source_priority BETWEEN 0 AND 1000),
  CONSTRAINT chk_entity_observation_binding_resolution
    CHECK (resolution_basis IN ('controller-issued-id', 'legacy-path-provisioning',
      'reviewed-reconciliation', 'deterministic-asset-anchor')),
  CONSTRAINT chk_entity_observation_binding_time
    CHECK (time_basis IN ('source-event-time', 'controller-receipt-time', 'legacy-unknown-start')),
  CONSTRAINT chk_entity_observation_binding_interval CHECK (valid_to IS NULL OR valid_to > valid_from),
  CONSTRAINT chk_entity_observation_binding_revision CHECK (revision > 0),
  CONSTRAINT chk_entity_observation_binding_digest CHECK (binding_digest ~ '^sha256:[0-9a-f]{64}$')
);

CREATE INDEX IF NOT EXISTS idx_entity_observation_binding_resolve
  ON public.entity_observation_binding
    (scope_key, binding_kind, topic_path, valid_from DESC, valid_to DESC NULLS FIRST);
CREATE INDEX IF NOT EXISTS idx_entity_observation_binding_entity
  ON public.entity_observation_binding
    (scope_key, stable_entity_id, valid_from DESC, valid_to DESC NULLS FIRST);
CREATE INDEX IF NOT EXISTS idx_entity_observation_binding_source
  ON public.entity_observation_binding
    (source_workload_identity_id, scope_key, binding_kind, topic_path);
CREATE UNIQUE INDEX IF NOT EXISTS uq_entity_observation_binding_current_source
  ON public.entity_observation_binding
    (scope_key, stable_entity_id, binding_kind, topic_path, source_workload_identity_id)
  WHERE valid_to IS NULL;

CREATE UNIQUE INDEX IF NOT EXISTS uq_entity_observation_binding_current_legacy
  ON public.entity_observation_binding
    (scope_key, stable_entity_id, binding_kind, topic_path)
  WHERE valid_to IS NULL
    AND source_authority = 'controller-legacy'
    AND source_workload_identity_id IS NULL;

CREATE OR REPLACE FUNCTION public.bump_entity_observation_binding_revision()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  IF NEW.revision <= OLD.revision THEN
    NEW.revision := nextval('public.entity_observation_binding_revision_seq');
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_entity_observation_binding_revision ON public.entity_observation_binding;
CREATE TRIGGER trg_entity_observation_binding_revision
  BEFORE UPDATE ON public.entity_observation_binding
  FOR EACH ROW EXECUTE FUNCTION public.bump_entity_observation_binding_revision();

CREATE OR REPLACE FUNCTION public.enforce_entity_observation_binding_ownership()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  PERFORM pg_advisory_xact_lock(
    hashtextextended(NEW.scope_key || ':' || NEW.binding_kind || ':' || NEW.topic_path, 0)
  );
  IF EXISTS (
    SELECT 1 FROM public.entity_observation_binding existing
     WHERE existing.scope_key = NEW.scope_key
       AND existing.binding_kind = NEW.binding_kind
       AND existing.topic_path = NEW.topic_path
       AND existing.stable_entity_id <> NEW.stable_entity_id
       AND existing.observation_binding_id <> NEW.observation_binding_id
       AND tstzrange(existing.valid_from, existing.valid_to, '[)')
           && tstzrange(NEW.valid_from, NEW.valid_to, '[)')
  ) THEN
    RAISE EXCEPTION 'observation topic interval is already owned by another entity'
      USING ERRCODE = '23505';
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_entity_observation_binding_ownership ON public.entity_observation_binding;
CREATE TRIGGER trg_entity_observation_binding_ownership
  BEFORE INSERT OR UPDATE OF scope_key, stable_entity_id, binding_kind, topic_path, valid_from, valid_to
  ON public.entity_observation_binding
  FOR EACH ROW EXECUTE FUNCTION public.enforce_entity_observation_binding_ownership();

CREATE TABLE IF NOT EXISTS public.asset_identity_transition (
  transition_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  scope_key text NOT NULL,
  canonical_stable_entity_id uuid NOT NULL,
  provisional_stable_entity_id uuid NULL,
  old_asset_path text NOT NULL,
  candidate_asset_path text NOT NULL,
  source_workload_identity_id uuid NOT NULL,
  state text NOT NULL DEFAULT 'observing',
  first_new_observation_at timestamptz NOT NULL,
  last_new_observation_at timestamptz NOT NULL,
  last_old_observation_at timestamptz NULL,
  process_heartbeat_at timestamptz NULL,
  handover_observed_at timestamptz NULL,
  grace_deadline timestamptz NULL,
  liveness_evidence_json jsonb NOT NULL DEFAULT '{}'::jsonb,
  decision text NOT NULL DEFAULT 'pending',
  decision_reason text NULL,
  decided_at timestamptz NULL,
  decided_by text NULL,
  policy_version integer NOT NULL,
  revision bigint NOT NULL DEFAULT 1,
  transition_digest text NOT NULL,
  audit_json jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (scope_key, transition_id),
  FOREIGN KEY (scope_key) REFERENCES public.platform_tenant(scope_key) ON DELETE RESTRICT,
  FOREIGN KEY (scope_key, canonical_stable_entity_id)
    REFERENCES public.entity(scope_key, stable_entity_id) ON DELETE RESTRICT,
  FOREIGN KEY (scope_key, provisional_stable_entity_id)
    REFERENCES public.entity(scope_key, stable_entity_id) ON DELETE RESTRICT,
  FOREIGN KEY (source_workload_identity_id)
    REFERENCES public.auth_workload_identities("id") ON DELETE RESTRICT,
  CONSTRAINT chk_asset_identity_transition_distinct_entities
    CHECK (provisional_stable_entity_id IS NULL
      OR provisional_stable_entity_id <> canonical_stable_entity_id),
  CONSTRAINT chk_asset_identity_transition_paths
    CHECK (length(btrim(old_asset_path)) > 0 AND length(btrim(candidate_asset_path)) > 0
      AND old_asset_path = btrim(old_asset_path) AND candidate_asset_path = btrim(candidate_asset_path)
      AND old_asset_path !~ '(^/|/$|//|[+#])' AND candidate_asset_path !~ '(^/|/$|//|[+#])'
      AND old_asset_path <> candidate_asset_path),
  CONSTRAINT chk_asset_identity_transition_state
    CHECK (state IN ('observing', 'grace', 'ready', 'accepted', 'rejected', 'conflict', 'expired')),
  CONSTRAINT chk_asset_identity_transition_observation_order
    CHECK (last_new_observation_at >= first_new_observation_at),
  CONSTRAINT chk_asset_identity_transition_grace
    CHECK (grace_deadline IS NULL OR grace_deadline >= first_new_observation_at),
  CONSTRAINT chk_asset_identity_transition_decision
    CHECK (decision IN ('pending', 'automatic-cutover', 'review-accepted', 'review-rejected', 'conflict')),
  CONSTRAINT chk_asset_identity_transition_decision_audit
    CHECK ((decision = 'pending' AND decided_at IS NULL AND decided_by IS NULL)
      OR (decision <> 'pending' AND decided_at IS NOT NULL)),
  CONSTRAINT chk_asset_identity_transition_policy CHECK (policy_version > 0),
  CONSTRAINT chk_asset_identity_transition_revision CHECK (revision > 0),
  CONSTRAINT chk_asset_identity_transition_digest CHECK (transition_digest ~ '^sha256:[0-9a-f]{64}$')
);

CREATE UNIQUE INDEX IF NOT EXISTS uq_asset_identity_transition_active_candidate
  ON public.asset_identity_transition
    (scope_key, canonical_stable_entity_id, candidate_asset_path)
  WHERE state IN ('observing', 'grace', 'ready');
CREATE INDEX IF NOT EXISTS idx_asset_identity_transition_resume
  ON public.asset_identity_transition (scope_key, state, grace_deadline, updated_at);
CREATE INDEX IF NOT EXISTS idx_asset_identity_transition_source
  ON public.asset_identity_transition (source_workload_identity_id, scope_key, state);

CREATE TABLE IF NOT EXISTS public.asset_identity_review_decision (
  review_decision_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  scope_key text NOT NULL,
  candidate_key text NOT NULL,
  canonical_stable_entity_id uuid NOT NULL,
  provisional_stable_entity_id uuid NOT NULL,
  old_asset_path text NOT NULL,
  candidate_asset_path text NOT NULL,
  decision text NOT NULL,
  evidence_digest text NOT NULL,
  evidence_json jsonb NOT NULL DEFAULT '{}'::jsonb,
  decided_at timestamptz NOT NULL,
  decided_by text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (scope_key, candidate_key),
  UNIQUE (scope_key, provisional_stable_entity_id),
  FOREIGN KEY (scope_key) REFERENCES public.platform_tenant(scope_key) ON DELETE RESTRICT,
  FOREIGN KEY (scope_key, canonical_stable_entity_id)
    REFERENCES public.entity(scope_key, stable_entity_id) ON DELETE RESTRICT,
  FOREIGN KEY (scope_key, provisional_stable_entity_id)
    REFERENCES public.entity(scope_key, stable_entity_id) ON DELETE RESTRICT,
  CONSTRAINT chk_asset_identity_review_distinct_entities
    CHECK (canonical_stable_entity_id <> provisional_stable_entity_id),
  CONSTRAINT chk_asset_identity_review_paths
    CHECK (length(btrim(old_asset_path)) > 0 AND length(btrim(candidate_asset_path)) > 0
      AND old_asset_path = btrim(old_asset_path) AND candidate_asset_path = btrim(candidate_asset_path)
      AND old_asset_path !~ '(^/|/$|//|[+#])' AND candidate_asset_path !~ '(^/|/$|//|[+#])'
      AND old_asset_path <> candidate_asset_path),
  CONSTRAINT chk_asset_identity_review_decision CHECK (decision IN ('accepted', 'rejected')),
  CONSTRAINT chk_asset_identity_review_candidate_key CHECK (candidate_key ~ '^sha256:[0-9a-f]{64}$'),
  CONSTRAINT chk_asset_identity_review_evidence_digest CHECK (evidence_digest ~ '^sha256:[0-9a-f]{64}$'),
  CONSTRAINT chk_asset_identity_review_actor CHECK (length(btrim(decided_by)) > 0)
);

CREATE INDEX IF NOT EXISTS idx_asset_identity_review_decision_time
  ON public.asset_identity_review_decision (scope_key, decided_at DESC);

CREATE OR REPLACE FUNCTION public.bump_asset_identity_transition_revision()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  IF NEW.revision <= OLD.revision THEN
    NEW.revision := OLD.revision + 1;
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_asset_identity_transition_revision ON public.asset_identity_transition;
CREATE TRIGGER trg_asset_identity_transition_revision
  BEFORE UPDATE ON public.asset_identity_transition
  FOR EACH ROW EXECUTE FUNCTION public.bump_asset_identity_transition_revision();

CREATE TABLE IF NOT EXISTS public.entity_binding_invalidation_outbox (
  outbox_event_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  scope_key text NOT NULL,
  transition_id uuid NOT NULL,
  binding_revision bigint NOT NULL,
  topic_paths jsonb NOT NULL,
  payload_json jsonb NOT NULL,
  delivery_status text NOT NULL DEFAULT 'pending',
  attempt_count integer NOT NULL DEFAULT 0,
  last_error_code text NULL,
  published_at timestamptz NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (scope_key, transition_id),
  FOREIGN KEY (scope_key) REFERENCES public.platform_tenant(scope_key) ON DELETE RESTRICT,
  FOREIGN KEY (scope_key, transition_id)
    REFERENCES public.asset_identity_transition(scope_key, transition_id) ON DELETE RESTRICT,
  CONSTRAINT chk_entity_binding_invalidation_revision CHECK (binding_revision > 0),
  CONSTRAINT chk_entity_binding_invalidation_topics
    CHECK (jsonb_typeof(topic_paths) = 'array' AND jsonb_array_length(topic_paths) > 0),
  CONSTRAINT chk_entity_binding_invalidation_payload CHECK (jsonb_typeof(payload_json) = 'object'),
  CONSTRAINT chk_entity_binding_invalidation_delivery
    CHECK (delivery_status IN ('pending', 'published')),
  CONSTRAINT chk_entity_binding_invalidation_attempts CHECK (attempt_count >= 0),
  CONSTRAINT chk_entity_binding_invalidation_publication
    CHECK ((delivery_status = 'published' AND published_at IS NOT NULL)
      OR (delivery_status = 'pending' AND published_at IS NULL))
);

CREATE INDEX IF NOT EXISTS idx_entity_binding_invalidation_delivery
  ON public.entity_binding_invalidation_outbox
    (delivery_status, binding_revision, created_at, outbox_event_id);

CREATE TABLE IF NOT EXISTS public.entity_migration_ledger (
  migration_ledger_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  scope_key text NOT NULL,
  source_table text NOT NULL,
  source_primary_key bigint NOT NULL,
  rule_version integer NOT NULL,
  source_digest text NOT NULL,
  first_plan_digest text NOT NULL,
  last_plan_digest text NOT NULL,
  first_source_outcome text NOT NULL,
  last_source_outcome text NOT NULL,
  last_apply_outcome text NOT NULL,
  stable_entity_id uuid NULL,
  evidence_json jsonb NOT NULL,
  last_result_json jsonb NOT NULL DEFAULT '{}'::jsonb,
  attempt_count integer NOT NULL DEFAULT 1,
  first_reviewed_at timestamptz NOT NULL,
  last_reviewed_at timestamptz NOT NULL,
  last_reviewed_by text NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (scope_key, source_table, source_primary_key, rule_version, source_digest),
  FOREIGN KEY (scope_key)
    REFERENCES public.platform_tenant(scope_key) ON DELETE RESTRICT,
  CONSTRAINT chk_entity_migration_ledger_source
    CHECK (source_table = 'uns_object'),
  CONSTRAINT chk_entity_migration_ledger_rule
    CHECK (rule_version > 0),
  CONSTRAINT chk_entity_migration_ledger_source_digest
    CHECK (source_digest ~ '^sha256:[0-9a-f]{64}$'),
  CONSTRAINT chk_entity_migration_ledger_first_plan_digest
    CHECK (first_plan_digest ~ '^sha256:[0-9a-f]{64}$'),
  CONSTRAINT chk_entity_migration_ledger_last_plan_digest
    CHECK (last_plan_digest ~ '^sha256:[0-9a-f]{64}$'),
  CONSTRAINT chk_entity_migration_ledger_source_outcome
    CHECK (
      first_source_outcome IN ('ready', 'migrated')
      AND last_source_outcome IN ('ready', 'migrated')
    ),
  CONSTRAINT chk_entity_migration_ledger_apply_outcome
    CHECK (last_apply_outcome IN ('applied', 'unchanged')),
  CONSTRAINT chk_entity_migration_ledger_attempt_count
    CHECK (attempt_count > 0),
  CONSTRAINT chk_entity_migration_ledger_review_order
    CHECK (last_reviewed_at >= first_reviewed_at)
);

CREATE INDEX IF NOT EXISTS idx_entity_migration_ledger_entity
  ON public.entity_migration_ledger (scope_key, stable_entity_id, last_reviewed_at DESC);

CREATE INDEX IF NOT EXISTS idx_entity_migration_ledger_review
  ON public.entity_migration_ledger (scope_key, last_apply_outcome, last_reviewed_at DESC);

CREATE TABLE IF NOT EXISTS public.entity_compatibility_outbox (
  outbox_event_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  scope_key text NOT NULL,
  event_key text NOT NULL,
  event_type text NOT NULL,
  source_table text NOT NULL,
  source_primary_key bigint NOT NULL,
  stable_entity_id uuid NULL,
  source_digest text NOT NULL,
  source_outcome text NOT NULL,
  sync_outcome text NOT NULL,
  delivery_status text NOT NULL DEFAULT 'pending',
  payload_json jsonb NOT NULL,
  last_error_code text NULL,
  attempt_count integer NOT NULL DEFAULT 1,
  first_observed_at timestamptz NOT NULL,
  last_observed_at timestamptz NOT NULL,
  published_at timestamptz NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (scope_key, event_key),
  FOREIGN KEY (scope_key)
    REFERENCES public.platform_tenant(scope_key) ON DELETE RESTRICT,
  CONSTRAINT chk_entity_compatibility_outbox_event_key
    CHECK (event_key ~ '^sha256:[0-9a-f]{64}$'),
  CONSTRAINT chk_entity_compatibility_outbox_event_type
    CHECK (event_type IN ('legacy_object_id_upserted')),
  CONSTRAINT chk_entity_compatibility_outbox_source
    CHECK (source_table = 'uns_object'),
  CONSTRAINT chk_entity_compatibility_outbox_source_digest
    CHECK (source_digest ~ '^sha256:[0-9a-f]{64}$'),
  CONSTRAINT chk_entity_compatibility_outbox_source_outcome
    CHECK (source_outcome IN ('ready', 'migrated', 'skipped', 'unmapped', 'ambiguous', 'failed')),
  CONSTRAINT chk_entity_compatibility_outbox_sync_outcome
    CHECK (sync_outcome IN ('synchronized', 'deferred', 'failed')),
  CONSTRAINT chk_entity_compatibility_outbox_delivery
    CHECK (delivery_status IN ('pending', 'published', 'failed')),
  CONSTRAINT chk_entity_compatibility_outbox_attempt_count
    CHECK (attempt_count > 0),
  CONSTRAINT chk_entity_compatibility_outbox_observed_order
    CHECK (last_observed_at >= first_observed_at)
);

CREATE INDEX IF NOT EXISTS idx_entity_compatibility_outbox_delivery
  ON public.entity_compatibility_outbox (delivery_status, created_at, outbox_event_id);

CREATE INDEX IF NOT EXISTS idx_entity_compatibility_outbox_source
  ON public.entity_compatibility_outbox (scope_key, source_primary_key, last_observed_at DESC);

-- Stable relationship endpoints are additive to the 1.x object-type/object-id
-- columns. Nullable tenant-local foreign keys allow reviewed migration without
-- making legacy relationship rows unreadable while an endpoint is unresolved.
ALTER TABLE public.object_id_relationship
  DROP CONSTRAINT IF EXISTS fk_object_id_relationship_scope;
ALTER TABLE public.object_id_relationship
  ADD CONSTRAINT fk_object_id_relationship_scope
  FOREIGN KEY (scope_key)
  REFERENCES public.platform_tenant(scope_key) ON DELETE RESTRICT
  NOT VALID;
ALTER TABLE public.object_id_relationship
  VALIDATE CONSTRAINT fk_object_id_relationship_scope;

ALTER TABLE public.object_id_relationship
  DROP CONSTRAINT IF EXISTS fk_object_id_relationship_stable_source;
ALTER TABLE public.object_id_relationship
  ADD CONSTRAINT fk_object_id_relationship_stable_source
  FOREIGN KEY (scope_key, source_stable_entity_id)
  REFERENCES public.entity(scope_key, stable_entity_id) ON DELETE RESTRICT
  NOT VALID;
ALTER TABLE public.object_id_relationship
  VALIDATE CONSTRAINT fk_object_id_relationship_stable_source;

ALTER TABLE public.object_id_relationship
  DROP CONSTRAINT IF EXISTS fk_object_id_relationship_stable_target;
ALTER TABLE public.object_id_relationship
  ADD CONSTRAINT fk_object_id_relationship_stable_target
  FOREIGN KEY (scope_key, target_stable_entity_id)
  REFERENCES public.entity(scope_key, stable_entity_id) ON DELETE RESTRICT
  NOT VALID;
ALTER TABLE public.object_id_relationship
  VALIDATE CONSTRAINT fk_object_id_relationship_stable_target;

ALTER TABLE public.object_id_relationship
  DROP CONSTRAINT IF EXISTS chk_object_id_relationship_endpoint_resolution;
ALTER TABLE public.object_id_relationship
  ADD CONSTRAINT chk_object_id_relationship_endpoint_resolution
  CHECK (
    endpoint_resolution_status IN ('legacy', 'resolved', 'unmapped', 'ambiguous', 'failed')
    AND (
      endpoint_resolution_status <> 'resolved'
      OR (
        scope_key IS NOT NULL
        AND source_stable_entity_id IS NOT NULL
        AND target_stable_entity_id IS NOT NULL
      )
    )
  ) NOT VALID;
ALTER TABLE public.object_id_relationship
  VALIDATE CONSTRAINT chk_object_id_relationship_endpoint_resolution;

ALTER TABLE public.object_id_relationship
  DROP CONSTRAINT IF EXISTS chk_object_id_relationship_valid_interval;
ALTER TABLE public.object_id_relationship
  ADD CONSTRAINT chk_object_id_relationship_valid_interval
  CHECK (valid_to IS NULL OR valid_from IS NULL OR valid_to > valid_from)
  NOT VALID;

CREATE TABLE IF NOT EXISTS public.entity_relationship_migration_ledger (
  relationship_migration_ledger_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  scope_key text NOT NULL,
  source_relationship_id integer NOT NULL,
  rule_version integer NOT NULL,
  source_digest text NOT NULL,
  first_plan_digest text NOT NULL,
  last_plan_digest text NOT NULL,
  source_stable_entity_id uuid NOT NULL,
  target_stable_entity_id uuid NOT NULL,
  last_apply_outcome text NOT NULL,
  evidence_json jsonb NOT NULL,
  attempt_count integer NOT NULL DEFAULT 1,
  first_reviewed_at timestamptz NOT NULL,
  last_reviewed_at timestamptz NOT NULL,
  last_reviewed_by text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (scope_key, source_relationship_id, rule_version, source_digest),
  FOREIGN KEY (scope_key)
    REFERENCES public.platform_tenant(scope_key) ON DELETE RESTRICT,
  FOREIGN KEY (source_relationship_id)
    REFERENCES public.object_id_relationship(id) ON DELETE RESTRICT,
  FOREIGN KEY (scope_key, source_stable_entity_id)
    REFERENCES public.entity(scope_key, stable_entity_id) ON DELETE RESTRICT,
  FOREIGN KEY (scope_key, target_stable_entity_id)
    REFERENCES public.entity(scope_key, stable_entity_id) ON DELETE RESTRICT,
  CONSTRAINT chk_entity_relationship_migration_rule CHECK (rule_version > 0),
  CONSTRAINT chk_entity_relationship_migration_source_digest
    CHECK (source_digest ~ '^sha256:[0-9a-f]{64}$'),
  CONSTRAINT chk_entity_relationship_migration_first_plan_digest
    CHECK (first_plan_digest ~ '^sha256:[0-9a-f]{64}$'),
  CONSTRAINT chk_entity_relationship_migration_last_plan_digest
    CHECK (last_plan_digest ~ '^sha256:[0-9a-f]{64}$'),
  CONSTRAINT chk_entity_relationship_migration_outcome
    CHECK (last_apply_outcome IN ('applied', 'unchanged')),
  CONSTRAINT chk_entity_relationship_migration_attempt_count CHECK (attempt_count > 0),
  CONSTRAINT chk_entity_relationship_migration_review_order
    CHECK (last_reviewed_at >= first_reviewed_at)
);

CREATE INDEX IF NOT EXISTS idx_entity_relationship_migration_review
  ON public.entity_relationship_migration_ledger
    (scope_key, last_apply_outcome, last_reviewed_at DESC);

CREATE TABLE IF NOT EXISTS public.entity_lifecycle_operation (
  lifecycle_operation_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  scope_key text NOT NULL,
  request_key text NOT NULL,
  operation_kind text NOT NULL,
  primary_stable_entity_id uuid NOT NULL,
  occurred_at timestamptz NOT NULL,
  actor text NOT NULL,
  reason text NULL,
  input_digest text NOT NULL,
  input_json jsonb NOT NULL,
  result_json jsonb NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (scope_key, request_key),
  FOREIGN KEY (scope_key)
    REFERENCES public.platform_tenant(scope_key) ON DELETE RESTRICT,
  FOREIGN KEY (scope_key, primary_stable_entity_id)
    REFERENCES public.entity(scope_key, stable_entity_id) ON DELETE RESTRICT,
  CONSTRAINT chk_entity_lifecycle_request_key CHECK (length(btrim(request_key)) > 0),
  CONSTRAINT chk_entity_lifecycle_kind
    CHECK (operation_kind IN ('move', 'rename', 'archive', 'merge', 'split')),
  CONSTRAINT chk_entity_lifecycle_actor CHECK (length(btrim(actor)) > 0),
  CONSTRAINT chk_entity_lifecycle_input_digest
    CHECK (input_digest ~ '^sha256:[0-9a-f]{64}$')
);

CREATE INDEX IF NOT EXISTS idx_entity_lifecycle_operation_entity
  ON public.entity_lifecycle_operation
    (scope_key, primary_stable_entity_id, occurred_at DESC);

CREATE TABLE IF NOT EXISTS public.entity_lineage (
  entity_lineage_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  scope_key text NOT NULL,
  lifecycle_operation_id uuid NOT NULL,
  lineage_kind text NOT NULL,
  predecessor_stable_entity_id uuid NOT NULL,
  successor_stable_entity_id uuid NOT NULL,
  valid_from timestamptz NOT NULL,
  evidence_json jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (
    scope_key,
    lifecycle_operation_id,
    predecessor_stable_entity_id,
    successor_stable_entity_id
  ),
  FOREIGN KEY (scope_key)
    REFERENCES public.platform_tenant(scope_key) ON DELETE RESTRICT,
  FOREIGN KEY (lifecycle_operation_id)
    REFERENCES public.entity_lifecycle_operation(lifecycle_operation_id) ON DELETE RESTRICT,
  FOREIGN KEY (scope_key, predecessor_stable_entity_id)
    REFERENCES public.entity(scope_key, stable_entity_id) ON DELETE RESTRICT,
  FOREIGN KEY (scope_key, successor_stable_entity_id)
    REFERENCES public.entity(scope_key, stable_entity_id) ON DELETE RESTRICT,
  CONSTRAINT chk_entity_lineage_kind CHECK (lineage_kind IN ('merge', 'split')),
  CONSTRAINT chk_entity_lineage_distinct CHECK (predecessor_stable_entity_id <> successor_stable_entity_id)
);

CREATE INDEX IF NOT EXISTS idx_entity_lineage_predecessor
  ON public.entity_lineage (scope_key, predecessor_stable_entity_id, valid_from DESC);

CREATE INDEX IF NOT EXISTS idx_entity_lineage_successor
  ON public.entity_lineage (scope_key, successor_stable_entity_id, valid_from DESC);

