CREATE TABLE IF NOT EXISTS public."chat_usage" (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "requestId" uuid NOT NULL UNIQUE,
  "threadId" uuid NULL,
  "userId" text NULL,
  "provider" text NOT NULL,
  "model" text NOT NULL,
  "promptTokens" integer NOT NULL DEFAULT 0,
  "completionTokens" integer NOT NULL DEFAULT 0,
  "totalTokens" integer NOT NULL DEFAULT 0,
  -- Tokens served from the provider's prompt cache (OpenAI
  -- usage.prompt_tokens_details.cached_tokens).  Nullable to
  -- distinguish "no cached-tokens metadata for this request" (older
  -- rows, non-OpenAI providers) from 0 (call ran with zero cache).
  "cachedPromptTokens" integer NULL,
  "llmCalls" integer NOT NULL DEFAULT 0,
  "traceEvents" jsonb NOT NULL DEFAULT '[]'::jsonb,
  "feedback" text NULL,
  "feedbackAt" timestamptz NULL,
  "createdAt" timestamptz NOT NULL DEFAULT now()
);

