-- === CHAT BACKGROUND JOBS TABLE ============================================
-- Disabled-by-default scaffold for Responses background mode. Jobs are only
-- created by future opt-in flows; the table lets admin tooling poll/cancel
-- provider-side background Responses without changing normal chat behavior.
CREATE TABLE IF NOT EXISTS public."chat_background_jobs" (
  "jobId" uuid PRIMARY KEY,
  "requestId" uuid NULL,
  "threadId" uuid NULL,
  "userId" text NULL,
  "provider" text NOT NULL,
  "model" text NOT NULL,
  "lane" text NULL,
  "status" text NOT NULL DEFAULT 'queued',
  "providerResponseId" text NULL,
  "providerRequestId" text NULL,
  "cursor" text NULL,
  "cancelRequested" boolean NOT NULL DEFAULT false,
  "error" text NULL,
  "outputText" text NULL,
  "responseJson" jsonb NULL,
  "metadata" jsonb NULL,
  "createdAt" timestamptz NOT NULL DEFAULT now(),
  "updatedAt" timestamptz NOT NULL DEFAULT now(),
  "startedAt" timestamptz NULL,
  "lastPolledAt" timestamptz NULL,
  "completedAt" timestamptz NULL
);

