-- ── Saved chart views (Phase 5a) ────────────────────────────────────────
-- Stores user-authored "Explore dialog" configurations so users can
-- come back to the same series + time window + offsets without
-- rebuilding them.  `spec` is a JSONB blob serialising the
-- ChartViewSpec shape; keeping it as a single opaque column lets the
-- spec evolve (new fields, per-series settings) without migrations.
-- Visibility:
--   'private' = only the owner sees + edits
--   'team'    = every authenticated user reads; only owner edits/deletes
-- Ownership is by `ownerEmail` (falls back to user id in resolvers
-- when email is missing).
CREATE TABLE IF NOT EXISTS public."chart_views" (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  name text NOT NULL,
  description text NULL,
  spec jsonb NOT NULL,
  "ownerEmail" text NOT NULL,
  visibility text NOT NULL DEFAULT 'private',
  "createdAt" timestamptz NOT NULL DEFAULT now(),
  "updatedAt" timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT chart_views_visibility_chk CHECK (visibility IN ('private', 'team'))
);

CREATE INDEX IF NOT EXISTS chart_views_owner_idx
  ON public."chart_views" ("ownerEmail");
CREATE INDEX IF NOT EXISTS chart_views_visibility_idx
  ON public."chart_views" (visibility)
  WHERE visibility <> 'private';
CREATE INDEX IF NOT EXISTS chart_views_updated_idx
  ON public."chart_views" ("updatedAt" DESC);

-- Phase 5c: view scoping.
--   scope = 'blank'      → saved from Explore toolbar (no primary attribute)
--   scope = 'attribute'  → saved while viewing a specific attribute (scopedTopic holds the fullTopic)
-- Rationale: a view saved while looking at attribute A is tuned for A's series
-- context — showing it in attribute B's menu and silently layering A's overlays
-- on B gave the wrong data.  Scoping means each attribute's menu shows only
-- views that belong to it; blank Explore shows blank-scope views plus a
-- separate "From attributes" section.
ALTER TABLE public."chart_views"
  ADD COLUMN IF NOT EXISTS scope text NOT NULL DEFAULT 'blank';
ALTER TABLE public."chart_views"
  ADD COLUMN IF NOT EXISTS "scopedTopic" text NULL;

-- Constraint: scope must be one of the two known values.  Added
-- separately so the default + backfill run first.
DO $$ BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'chart_views_scope_chk'
      AND conrelid = 'public."chart_views"'::regclass
  ) THEN
    ALTER TABLE public."chart_views"
      ADD CONSTRAINT chart_views_scope_chk
        CHECK (scope IN ('blank', 'attribute'));
  END IF;
END $$;

-- Backfill: existing rows are derived from their spec JSON.  Rows whose
-- spec.primary.fullTopic is a string become 'attribute'; everything else
-- stays 'blank' (the DEFAULT).  Idempotent — only touches rows still at
-- the default value, so re-running init.sql doesn't churn later edits.
UPDATE public."chart_views"
SET scope = 'attribute',
    "scopedTopic" = spec->'primary'->>'fullTopic'
WHERE scope = 'blank'
  AND jsonb_typeof(spec->'primary') = 'object'
  AND spec->'primary'->>'fullTopic' IS NOT NULL
  AND length(spec->'primary'->>'fullTopic') > 0;

CREATE INDEX IF NOT EXISTS chart_views_scoped_topic_idx
  ON public."chart_views" ("scopedTopic")
  WHERE "scopedTopic" IS NOT NULL;

-- ── Saved UNS table views ───────────────────────────────────────────────
-- Stores user-authored table-mode filters from the UNS tree/table page.
-- The spec is a JSONB blob so filter sets, column preferences, and future
-- pinned-attribute selections can evolve without schema churn.
-- Visibility mirrors chart_views and dashboards:
--   'private' = only the owner sees + edits
--   'team'    = every authenticated user reads; only owner edits/deletes
CREATE TABLE IF NOT EXISTS public."uns_table_views" (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  name text NOT NULL,
  description text NULL,
  spec jsonb NOT NULL,
  "ownerEmail" text NOT NULL,
  visibility text NOT NULL DEFAULT 'private',
  "createdAt" timestamptz NOT NULL DEFAULT now(),
  "updatedAt" timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT uns_table_views_visibility_chk CHECK (visibility IN ('private', 'team'))
);

CREATE INDEX IF NOT EXISTS uns_table_views_owner_idx
  ON public."uns_table_views" ("ownerEmail");
CREATE INDEX IF NOT EXISTS uns_table_views_visibility_idx
  ON public."uns_table_views" (visibility)
  WHERE visibility <> 'private';
CREATE INDEX IF NOT EXISTS uns_table_views_updated_idx
  ON public."uns_table_views" ("updatedAt" DESC);

-- Phase 6b: dashboards.  A dashboard is a grid of cells, each cell
-- referencing a saved chart view by id plus optional per-cell and
-- dashboard-level time overrides.  `layout` stores the full
-- DashboardLayout JSON (see apps/uns-datahub/src/app/dashboard/
-- dashboard-layout.ts for the schema).
--
-- Visibility model mirrors chart_views:
--   'private' — only the owner sees + edits
--   'team'    — every authenticated user reads; only owner edits/deletes
-- Ownership is by `ownerEmail`.
CREATE TABLE IF NOT EXISTS public."dashboards" (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  name text NOT NULL,
  description text NULL,
  layout jsonb NOT NULL,
  "ownerEmail" text NOT NULL,
  visibility text NOT NULL DEFAULT 'private',
  "createdAt" timestamptz NOT NULL DEFAULT now(),
  "updatedAt" timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT dashboards_visibility_chk CHECK (visibility IN ('private', 'team'))
);

CREATE INDEX IF NOT EXISTS dashboards_owner_idx
  ON public."dashboards" ("ownerEmail");
CREATE INDEX IF NOT EXISTS dashboards_visibility_idx
  ON public."dashboards" (visibility)
  WHERE visibility <> 'private';
CREATE INDEX IF NOT EXISTS dashboards_updated_idx
  ON public."dashboards" ("updatedAt" DESC);

-- ── trigger_definitions ───────────────────────────────────────────
-- Phase 6d (Trigger Service, Stage 1).  Reactive UNS data: when a
-- value matches a configured rule, publish a uns-kit message to a
-- new output topic.  Owned by the controller (auth-gated CRUD via
-- GraphQL); consumed by uns-api-global, which polls the
-- /api/triggers REST endpoint on boot + interval to keep its
-- in-process registry in sync.
--
-- Stage 1 supports three kinds:
--   high   — fire when value > config.threshold (edge-only)
--   low    — fire when value < config.threshold (edge-only)
--   event  — fire on value change, optionally filtered to
--            config.matchValues
-- Stage 2 adds: compare (cross-topic), string (specific match
-- with correlated reads).  Stage 3 adds the controller UI.
--
-- `config` is a JSON blob keyed off `kind`.  The resolver and the
-- consumer (uns-api-global) validate shape; Postgres just stores
-- it verbatim.
CREATE TABLE IF NOT EXISTS public."trigger_definitions" (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  name text NOT NULL,
  kind text NOT NULL,
  "sourceTopic" text NOT NULL,
  "outputTopic" text NOT NULL,
  config jsonb NOT NULL DEFAULT '{}'::jsonb,
  "cooldownMs" integer NULL,
  enabled boolean NOT NULL DEFAULT true,
  description text NULL,
  "createdBy" text NULL,
  "createdAt" timestamptz NOT NULL DEFAULT now(),
  "updatedAt" timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT trigger_definitions_kind_chk
    CHECK (kind IN ('high', 'low', 'event', 'compare', 'string', 'composite'))
);

-- Stage 4a + 5 — bring the existing constraint up to the latest
-- kind union when this script runs against a database that was
-- created before later kinds were added.  CREATE TABLE IF NOT
-- EXISTS skips the table when it exists, so the constraint update
-- needs to be its own statement.  The check looks for the newest
-- member ('composite') so the script is idempotent — re-runs
-- against an already-updated DB are no-ops.
DO $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'trigger_definitions_kind_chk'
      AND pg_get_constraintdef(oid) NOT LIKE '%composite%'
  ) THEN
    ALTER TABLE public."trigger_definitions"
      DROP CONSTRAINT trigger_definitions_kind_chk;
    ALTER TABLE public."trigger_definitions"
      ADD CONSTRAINT trigger_definitions_kind_chk
      CHECK (kind IN ('high', 'low', 'event', 'compare', 'string', 'composite'));
  END IF;
END$$;

CREATE INDEX IF NOT EXISTS trigger_definitions_enabled_idx
  ON public."trigger_definitions" (enabled)
  WHERE enabled = true;
CREATE INDEX IF NOT EXISTS trigger_definitions_source_idx
  ON public."trigger_definitions" ("sourceTopic")
  WHERE enabled = true;
CREATE INDEX IF NOT EXISTS trigger_definitions_updated_idx
  ON public."trigger_definitions" ("updatedAt" DESC);

-- === TRIGGER FIRES TABLE ====================================================
-- Stage 4a (Audit log).  Append-only history of trigger fires.
-- Populated by the controller's TriggerFiresRecorder which subscribes
-- to MQTT trigger output topics and persists each parsed uns-kit
-- payload's metadata + value.
--
-- Fields are denormalised (triggerName, kind, outputTopic) so a row
-- survives `DELETE FROM trigger_definitions` — the audit trail
-- shouldn't disappear when an admin deletes the rule.
--
-- `snapshots` is jsonb (only populated for kind='string' fires);
-- `value` is text (handles both numeric and string fires; admins
-- read it back as a string and the UI can numeric-ify when relevant).
--
-- Retention: a daily cron deletes rows older than 30 days (see
-- src/triggers/trigger-fires-retention.ts).  Tunable via the
-- TRIGGER_FIRES_RETENTION_DAYS constant in that file.
CREATE TABLE IF NOT EXISTS public."trigger_fires" (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  "triggerId" uuid NOT NULL,
  "triggerName" text NOT NULL,
  kind text NOT NULL,
  "outputTopic" text NOT NULL,
  "sourceTopic" text NOT NULL,
  value text NOT NULL,
  uom text NULL,
  "sourceTimestamp" timestamptz NULL,
  "firedAt" timestamptz NOT NULL DEFAULT now(),
  snapshots jsonb NULL
);

-- Hot path: "fires for this trigger, most recent first" (powers the
-- "Recent fires" tab in the trigger Edit dialog).
CREATE INDEX IF NOT EXISTS trigger_fires_trigger_id_fired_at_idx
  ON public."trigger_fires" ("triggerId", "firedAt" DESC);

-- Used by the daily TTL cron to find stale rows quickly.
CREATE INDEX IF NOT EXISTS trigger_fires_fired_at_idx
  ON public."trigger_fires" ("firedAt" DESC);

-- === CAPTURE DEFINITIONS ====================================================
-- Windowed logging automations.  A capture opens when startCondition
-- becomes true, closes when stopCondition becomes true, and emits selected
-- Data attributes as table-shaped UNS rows according to captureConfig.
--
-- Controller owns authoring/persistence; uns-api-global consumes enabled rows
-- from GET /api/captures and owns runtime session execution.
CREATE TABLE IF NOT EXISTS public."capture_definitions" (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  name text NOT NULL,
  "startCondition" jsonb NOT NULL,
  "stopCondition" jsonb NOT NULL,
  "inputMappings" jsonb NOT NULL,
  "outputTopic" text NOT NULL,
  "captureConfig" jsonb NOT NULL,
  enabled boolean NOT NULL DEFAULT true,
  description text NULL,
  "createdBy" text NULL,
  "createdAt" timestamptz NOT NULL DEFAULT now(),
  "updatedAt" timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT capture_definitions_start_condition_object_chk
    CHECK (jsonb_typeof("startCondition") = 'object'),
  CONSTRAINT capture_definitions_stop_condition_object_chk
    CHECK (jsonb_typeof("stopCondition") = 'object'),
  CONSTRAINT capture_definitions_input_mappings_array_chk
    CHECK (jsonb_typeof("inputMappings") = 'array'),
  CONSTRAINT capture_definitions_capture_config_object_chk
    CHECK (jsonb_typeof("captureConfig") = 'object')
);

CREATE INDEX IF NOT EXISTS capture_definitions_enabled_idx
  ON public."capture_definitions" (enabled)
  WHERE enabled = true;
CREATE INDEX IF NOT EXISTS capture_definitions_output_topic_idx
  ON public."capture_definitions" ("outputTopic");
CREATE INDEX IF NOT EXISTS capture_definitions_updated_idx
  ON public."capture_definitions" ("updatedAt" DESC);

-- Runtime audit for capture sessions.  Definitions stay controller-owned
-- configuration; sessions are evidence emitted by uns-api-global when a
-- capture window opens/closes.
CREATE TABLE IF NOT EXISTS public."capture_sessions" (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  "captureId" text NOT NULL,
  "captureName" text NOT NULL,
  "sessionId" text NOT NULL,
  "outputTopic" text NOT NULL,
  "startedAt" timestamptz NOT NULL,
  "endedAt" timestamptz NULL,
  "closeReason" text NULL,
  "rowCount" integer NOT NULL DEFAULT 0,
  "lastRowAt" timestamptz NULL,
  "lastSuppressedReason" text NULL,
  "runtimeProcess" text NULL,
  "controllerName" text NULL,
  "createdAt" timestamptz NOT NULL DEFAULT now(),
  "updatedAt" timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT capture_sessions_row_count_non_negative_chk CHECK ("rowCount" >= 0)
);

CREATE UNIQUE INDEX IF NOT EXISTS capture_sessions_capture_session_uidx
  ON public."capture_sessions" ("captureId", "sessionId");
CREATE INDEX IF NOT EXISTS capture_sessions_capture_started_idx
  ON public."capture_sessions" ("captureId", "startedAt" DESC);
CREATE INDEX IF NOT EXISTS capture_sessions_updated_idx
  ON public."capture_sessions" ("updatedAt" DESC);

-- === RAG STORAGE ============================================================
-- Controller-owned persistence for the uns-rag addon runtime. The runtime
-- must call controller APIs for durable state and must not connect to Postgres
-- directly. Embeddings are always kept as portable JSONB; when pgvector is
-- installed the optional embeddingVector column provides exact vector ranking.
CREATE TABLE IF NOT EXISTS public."rag_sources" (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  type text NOT NULL,
  "displayName" text NOT NULL,
  scope jsonb NOT NULL DEFAULT '{}'::jsonb,
  config jsonb NOT NULL DEFAULT '{}'::jsonb,
  "runtimeType" text NULL,
  "configStatus" text NOT NULL DEFAULT 'draft',
  "sourceStatus" text NOT NULL DEFAULT 'unknown',
  enabled boolean NOT NULL DEFAULT true,
  "lastScanAt" timestamptz NULL,
  "lastSuccessfulScanAt" timestamptz NULL,
  "lastError" text NULL,
  "createdBy" text NULL,
  "createdAt" timestamptz NOT NULL DEFAULT now(),
  "updatedAt" timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT rag_sources_type_chk
    CHECK (type IN ('local-folder', 'docuware', 'sharepoint', 's3')),
  CONSTRAINT rag_sources_scope_object_chk
    CHECK (jsonb_typeof(scope) = 'object'),
  CONSTRAINT rag_sources_config_object_chk
    CHECK (jsonb_typeof(config) = 'object')
);

