DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'rag_sources' AND column_name = 'name') THEN
    ALTER TABLE public."rag_sources" ALTER COLUMN name SET DEFAULT '';
  END IF;
  IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'rag_sources' AND column_name = 'uns_scope') THEN
    ALTER TABLE public."rag_sources" ALTER COLUMN uns_scope SET DEFAULT '';
  END IF;
  IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'rag_sources' AND column_name = 'local_path') THEN
    ALTER TABLE public."rag_sources" ALTER COLUMN local_path SET DEFAULT '';
  END IF;
  IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'rag_sources' AND column_name = 'metadata_json') THEN
    ALTER TABLE public."rag_sources" ALTER COLUMN metadata_json SET DEFAULT '{}'::jsonb;
  END IF;
  IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'rag_ingest_jobs' AND column_name = 'source_id') THEN
    ALTER TABLE public."rag_ingest_jobs"
