  IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'rag_documents' AND column_name = 'content_hash') THEN
    ALTER TABLE public."rag_documents" ALTER COLUMN content_hash SET DEFAULT '';
