  IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'rag_chunks' AND column_name = 'document_id') THEN
    ALTER TABLE public."rag_chunks"
      ALTER COLUMN document_id DROP NOT NULL,
