  END IF;
  IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'rag_chunks' AND column_name = 'source_id') THEN
    ALTER TABLE public."rag_chunks"
      ALTER COLUMN source_id DROP NOT NULL,
      ALTER COLUMN source_id DROP DEFAULT;
  END IF;
  IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'rag_chunks' AND column_name = 'uns_scope') THEN
    ALTER TABLE public."rag_chunks" ALTER COLUMN uns_scope SET DEFAULT '';
  END IF;
  IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'rag_chunks' AND column_name = 'chunk_index') THEN
    ALTER TABLE public."rag_chunks" ALTER COLUMN chunk_index SET DEFAULT 0;
  END IF;
  IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'rag_chunks' AND column_name = 'content') THEN
    ALTER TABLE public."rag_chunks" ALTER COLUMN content SET DEFAULT '';
  END IF;
  IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'rag_chunks' AND column_name = 'content_hash') THEN
    ALTER TABLE public."rag_chunks" ALTER COLUMN content_hash SET DEFAULT '';
  END IF;
  IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'rag_errors' AND column_name = 'code') THEN
    ALTER TABLE public."rag_errors" ALTER COLUMN code SET DEFAULT '';
  END IF;
  IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'rag_errors' AND column_name = 'message') THEN
    ALTER TABLE public."rag_errors" ALTER COLUMN message SET DEFAULT '';
  END IF;
  IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'rag_query_audit' AND column_name = 'request_id') THEN
    ALTER TABLE public."rag_query_audit" ALTER COLUMN request_id SET DEFAULT '';
