  IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'rag_query_audit' AND column_name = 'query_mode') THEN
    ALTER TABLE public."rag_query_audit" ALTER COLUMN query_mode SET DEFAULT '';
  END IF;
END
$$;

