-- === UNS TABLE SCHEMA METADATA =============================================
-- Durable, node-scoped table schema metadata for UNS Attribute nodes with
-- attributeType='Table'.  Capture outputs use this to persist the emitted
-- columns for a concrete `<asset>/capture/<id>/records/` leaf instead of
-- overloading the global `records` attribute schema.
CREATE TABLE IF NOT EXISTS public.uns_table_schema (
  id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  uns_object_id integer NOT NULL REFERENCES public.uns_object(id) ON DELETE CASCADE,
  full_topic text NOT NULL,
  schema_kind text NOT NULL DEFAULT 'table',
  source_kind text NULL,
  source_id text NULL,
  schema_json jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by text NULL,
  change_source text NULL,
  change_note text NULL
);

