  ADD COLUMN IF NOT EXISTS full_topic text;
ALTER TABLE public.uns_table_schema
  ADD COLUMN IF NOT EXISTS schema_kind text NOT NULL DEFAULT 'table';
ALTER TABLE public.uns_table_schema
  ADD COLUMN IF NOT EXISTS source_kind text;
ALTER TABLE public.uns_table_schema
  ADD COLUMN IF NOT EXISTS source_id text;
ALTER TABLE public.uns_table_schema
  ADD COLUMN IF NOT EXISTS schema_json jsonb NOT NULL DEFAULT '{}'::jsonb;
ALTER TABLE public.uns_table_schema
  ADD COLUMN IF NOT EXISTS created_at timestamptz NOT NULL DEFAULT now();
ALTER TABLE public.uns_table_schema
  ADD COLUMN IF NOT EXISTS updated_at timestamptz NOT NULL DEFAULT now();
